/* Researched town profiles: one paragraph per town written from the sources listed
   (town websites, Massachusetts Historical Commission / MACRIS, National Register, mass.gov).
   Built by scripts/town-extra/gera_ts.py. Do not add a sentence without a source. */

export interface TownProfile { paragraph: string; sources: string[]; checked: string }

export const TOWN_PROFILES: Record<string, TownProfile> = {
  "acton": { paragraph: "Acton's land was Concord grazing ground when the first homestead within today's boundaries went up in 1639, and the town became independent on July 3, 1735. The oldest home still standing, the Faulkner House, dates to 1707 and was built for Ephraim Jones; the main section of Jones Tavern, now on the National Register, followed in 1732. By the mid-1800s Acton was a center for barrel making, with a powder mill, three gristmills, and four sawmills, and the American Powder Mills made gunpowder from 1835 to 1940. The Fitchburg Railroad arrived on October 1, 1844, running through South Acton and West Acton to serve the mills. That history left five distinct villages: Acton Center, the civic seat since the Revolution; South Acton, once the most industrial; West Acton, the commercial strip on Route 111; East Acton, now largely residential; and North Acton, which grew after 1975. Population quadrupled between 1950 and 1970, from 3,510 to 14,770. Glaciers left nine drumlins and two kettle ponds, Wills Hole and Grassy Pond, and Nagog Pond forms the Littleton line.", sources: ["https://en.wikipedia.org/wiki/Acton,_Massachusetts"], checked: "2026-11-17" },
  "arlington": { paragraph: "Colonists settled Menotomy as a village of Cambridge in 1635; it was incorporated as West Cambridge on February 27, 1807, and took the name Arlington in 1867. Mill Brook did the early work, with Captain George Cooke's mill of 1637 the first of seven along the stream; the Old Schwamb Mill was federally listed in 1971. Spy Pond fed an ice trade that shipped to the Caribbean and India until the last ice house burned in 1930, and farms here grew a well-known local lettuce. The 1920s brought a 93 percent population jump, from 18,665 to 36,094, and today much of the housing is two- and three-family houses mixed with smaller single-family homes. The Jason Russell House, where 12 Americans died on April 19, 1775, still shows bullet holes inside. The Arlington Center Historic District takes in Robbins Library and Town Hall, while the Henry Swan House of 1888 stands at 418 Massachusetts Avenue. Ground rises from 4 feet at Alewife Brook to 377 feet near Park Avenue, and the Arlington Heights water tower went up in 1921.", sources: ["https://en.wikipedia.org/wiki/Arlington,_Massachusetts"], checked: "2026-11-17" },
  "ashland": { paragraph: "Ashland, called Unionville before 1846, was incorporated that year from nearly equal parts of Hopkinton, Holliston and Framingham and named for Henry Clay's Kentucky estate. The Boston & Worcester Railroad, built through during the 1830s, together with the Sudbury River drew mills and a boot and shoe industry. Three reservoirs that the Boston Water Board built on the river in 1878 halted further growth, including the Dwight Printing Company's planned granite mills. In the 20th century, Telechron, the electric clock maker, employed about 2,000 people at its 1950s peak, and GE made clocks here until 1979. After World War II the town changed from a rural place 22 miles west of Boston into a mostly residential suburb by the 1980s. Older homes of varying density line Route 135, while farms along Route 126 have given way to shopping centers and condominiums. The 1855 Ashland Town House at 101 Main Street, Greek Revival with Italianate brackets on a granite foundation, faces the 1835 Congregational meeting house.", sources: ["https://en.wikipedia.org/wiki/Ashland,_Massachusetts", "https://en.wikipedia.org/wiki/Ashland_Town_House"], checked: "2026-11-17" },
  "auburn": { paragraph: "Settlers arrived in 1714, but the town only took shape in 1778, assembled from slices of Worcester, Sutton, Leicester, and Oxford and named Ward after General Artemas Ward. Postal confusion with nearby Ware led to the name Auburn in 1837. The oldest documented house is the Joseph Stone House at 35 Stone Street, a one-and-a-half-story First Period timber frame whose north half dates to 1729, with two bays added in 1790. On Pakachoag Hill, Robert Goddard launched the first liquid-fueled rocket from the Asa Ward Farm on March 16, 1926; the spot is now the ninth fairway of the Pakachoag Golf Course and a National Historic Landmark. The two-room, wood-frame Tuttle Square School at 41 South Street, built in 1922 in a Craftsman style, now holds the Auburn Historical Museum. Postwar growth was steep: residents went from 8,840 in 1950 to 14,047 in 1960, as I-90, I-290, I-395, Route 12, and U.S. 20 converged on the town.", sources: ["https://en.wikipedia.org/wiki/Auburn,_Massachusetts", "https://en.wikipedia.org/wiki/Joseph_Stone_House", "https://en.wikipedia.org/wiki/Goddard_Rocket_Launching_Site", "https://en.wikipedia.org/wiki/Tuttle_Square_School"], checked: "2026-11-17" },
  "ayer": { paragraph: "A mill built in 1667 near Nonacoicus Brook marked the first settlement in what is now Ayer, then the southern edge of Groton. Rails turned that hamlet into a hub: the Fitchburg line arrived in 1844 and three more lines in 1848, and the area took the name Groton Junction. On February 14, 1871, it split from Groton and was named for Dr. James Cook Ayer, the Lowell medicine maker who paid for the Town Hall. A second force came in 1917 with Camp Devens, later Fort Devens, which shaped local commerce until the base closed in 1996. Population peaked at 14,927 in 1960, then fell to 8,325 by 1970. National Register listings include the Ayer Main Street Historic District, the Pleasant Street School, and St. Andrew's Church of 1892 on Faulkner Street. Main Street and Sandy Pond Road are believed to follow old Native trails, and the town touches the Nashua River, Sandy Pond, and Long Pond.", sources: ["https://en.wikipedia.org/wiki/Ayer,_Massachusetts"], checked: "2026-11-17" },
  "bedford": { paragraph: "Europeans first settled this land around 1640, but Bedford only became a town in 1729, assembled from roughly three-fifths Billerica and two-fifths Concord. Water shaped its early economy: the John Wilson Corne Mill on Vine Brook dates from about 1685, and a paper mill on the same brook employed many residents after the 1840s. On North Road, the Job Lane House is an early-1700s saltbox, restored and opened to visitors in season. Since 1977 the federal Register has included Bedford center, which holds Fitch Tavern and the Federal-style Elijah Stearns Mansion at 4 Great Road, built around 1800 with brick ends, four chimneys, and an arched glass doorway. Two newer districts, Wilson Mill-Old Burlington Road and Two Brothers Rocks-Dudley Road, were added in 2003 and 2010. The town's Unitarian Church dates to 1816, and Huckins Farm keeps a farmhouse Peter Farmer built in the 1840s. Population quadrupled between 1930 and 1960, from 2,603 to 10,969. The Concord River forms part of the town line, and the Shawsheen River runs through town.", sources: ["https://en.wikipedia.org/wiki/Bedford,_Massachusetts"], checked: "2026-11-17" },
  "bellingham": { paragraph: "Bellingham began as swampy land at the southwestern corner of the Dedham Grant, which Dedham thought unworthy of settlement, while land on the river's north side was bought by Edward Rawson; the two areas later merged. The first land here bought from Dedham was purchased in 1696, and the village, first called Westham, was incorporated on November 27, 1719, and named for colonial governor Richard Bellingham. During the Industrial Revolution several man-made ponds were built on former swamp to support industry. In Caryville, the former mill village in the northeastern corner that extends into Franklin, Joseph Fairbanks opened a mill in 1813; William H. Cary later rebuilt and enlarged it and built three tenement houses, and a 1918 mill on the site was demolished in 2016. The North Bellingham Cemetery on Hartford Avenue, with burials from 1712 to 1888, is the town's oldest. Interstate 495, built in 1965, crosses the northern end of town, while the southern part, which borders Woonsocket, Rhode Island, is mostly suburban.", sources: ["https://en.wikipedia.org/wiki/Bellingham,_Massachusetts", "https://en.wikipedia.org/wiki/Caryville,_Massachusetts", "https://en.wikipedia.org/wiki/North_Bellingham_Cemetery_and_Oak_Hill_Cemetery"], checked: "2026-11-17" },
  "belmont": { paragraph: "Carved in 1859 from parts of Watertown, Waltham and West Cambridge, Belmont took its name from Bellmont, the 200-acre estate of John Perkins Cushing, who also lent his name to Cushing Square. Before then the land was mostly large farms sending produce and livestock to Boston. Trolley lines, better roads and big estates drew residents around 1900, and the population roughly doubled during the 1920s, from 10,749 to 21,748. The Fitchburg Railroad shaped two of the three business districts: at Belmont Center a stone arch bridge, embankment and station were built in 1907, and at Waverley the tracks were lowered beneath Trapelo Road. Cushing Square anchors the south side. Belmont Hill, the main high ground, is known for its large houses, while most people live on the lower land around it. Town Hall dates to about 1913, designed by Hartwell and Richardson, and Redtop, once the home of William Dean Howells, still stands. A former clay pit off Concord Avenue became the site of Belmont High School and Clay Pit Pond.", sources: ["https://en.wikipedia.org/wiki/Belmont,_Massachusetts"], checked: "2026-11-17" },
  "berlin": { paragraph: "Berlin lies in a low range of hills between the Nashua River and Assabet River valleys, 12 miles northeast of Worcester. Settlers arrived in 1665 on land that the Nashaway sachem Sholan had partly deeded in 1643; the name Berlin dates to 1784, when it was made a district, and town status followed in 1812. Farming shaped the landscape: mixed hay, grain and cattle first, then market gardening that sent 41,000 bunches of asparagus to market in 1885, and poultry farms that produced 836,600 dozen eggs a year by 1940. After the Civil War a large shoe factory and lumbering offered other work. The former town hall at 12 Woodward Avenue, built in 1870 and enlarged in 1904, is a 2½-story wood-frame building with clapboards, corner pilasters and an 1875 portico in the Greek Revival manner. It faces the triangular green in the village center and has held National Register status since 2011. Interstate 495 and Route 62 cross the town.", sources: ["https://en.wikipedia.org/wiki/Berlin,_Massachusetts", "https://en.wikipedia.org/wiki/Berlin_Town_Hall_(Berlin,_Massachusetts)"], checked: "2026-11-17" },
  "beverly": { paragraph: "Part of Salem from its 1626 settlement under Roger Conant, Beverly was set off as a town in 1668 and became a city in 1894. Several First Period houses remain: the John Balch House, dated by tree-ring testing to about 1679, the John Hale House of about 1694 and the 1695 Exercise Conant House, followed by the John Cabot House of 1781. North Beverly held America's first cotton mill, the Beverly Cotton Manufactory of 1787. The Continental vessel Hannah was fitted out at Glover's Wharf and sailed from Beverly Harbor in 1775. The United Shoe Machinery Corporation raised a quarter-mile reinforced-concrete factory designed by Ernest L. Ransome, producing from 1906 until 1987. Beverly Farms and Prides Crossing drew summer residents such as Henry Clay Frick, and President Taft rented houses here from 1909 to 1912. The western side is more built up and the east more rural. Beverly Harbor lies at the mouth of the Danvers River, which the Bass River joins inside city limits, and Great and Little Misery Islands belong to the city.", sources: ["https://en.wikipedia.org/wiki/Beverly,_Massachusetts"], checked: "2026-11-17" },
  "blackstone": { paragraph: "European settlers reached this corner of Mendon in 1662, but Blackstone was set off as a separate municipality only in 1845, named for early colonist William Blaxton. The Blackstone River runs along part of the southern border, and its meeting with the Branch River shaped the village of Waterford, which straddles the Rhode Island line around St. Paul Street. Welcome and Darius Farnum came from Uxbridge in the 1820s, dammed the Branch River, and built the Red Mill; Mammoth Mill followed in 1864, and the Blackstone Canal of 1828 ran beside the river. On Main Street (Route 122), the small Farnum's Gate Historic District holds the Federal-style Welcome Farnum House of 1835, Greek Revival homes such as the temple-fronted Estus Lamb House, many 1840s houses built by local mill owners, and the Gothic Revival Federated Church of 1928. Farmland survives at 286 Mendon Street, where the Southwick-Daniels Farm keeps a farmhouse ell from about 1750, a main house of about 1830, and a barn from about 1850. Other villages include East Blackstone, Central Village, and Wheelockville.", sources: ["https://en.wikipedia.org/wiki/Blackstone,_Massachusetts", "https://en.wikipedia.org/wiki/Waterford,_Rhode_Island", "https://en.wikipedia.org/wiki/Farnum%27s_Gate_Historic_District", "https://en.wikipedia.org/wiki/Southwick-Daniels_Farm"], checked: "2026-11-17" },
  "bolton": { paragraph: "Bolton separated from Lancaster along the Still River, where the boundary still runs, and was incorporated on June 24, 1738, named for the Duke of Bolton. The Concord highway was laid out over Wattaquadock Hill in 1656, and by 1711 more than 150 people lived here; many early houses were protected by flankers and served as garrisons. Limestone was mined at the Bolton Lime Kiln and Quarry. By the early 19th century the town's focus had moved to the east-west road now called Route 117, a stagecoach stop with inns and taverns, and by 1830 the center looked much as it does today. Strung out along Main Street, the Bolton Center Historic District includes the first minister's house of about 1741 at 752 Main Street, the 1853 Town House, an 1812 powder house, an 1825 one-room schoolhouse and a 1903 Tudor Revival library. In the east, the flat Pan Historic District keeps Federal-period houses and the Pan Burying Ground near Routes 117 and 85. Farms and apple orchards remain, along with the Bolton Flats near the Nashua and Still Rivers.", sources: ["https://en.wikipedia.org/wiki/Bolton,_Massachusetts", "https://en.wikipedia.org/wiki/Bolton_Center_Historic_District", "https://en.wikipedia.org/wiki/Pan_Historic_District"], checked: "2026-11-17" },
  "boxborough": { paragraph: "Boxborough was carved from parts of Harvard, Littleton, and Stow; after three rejected petitions, residents won district status in 1782, and incorporation followed on February 25, 1783. Colonists arrived late, in the early 1700s, and John Wetherbee was building houses here by 1717. Farming defined the place, and it grew into one of the most productive agricultural areas in Middlesex County. The clearest record of that past lines Hill Road, where the Boxborough Old Town Center district, a National Register listing since 2006, holds 52 contributing properties dating from the 1770s to the early 20th century, mostly Colonial and Federal in style. That district takes in North Cemetery, the Reverend Joseph Willard House, and a one-room schoolhouse whose privy stayed in use into the mid-1900s. Also on Hill Road stands the Silas Wetherbee House of 1770, known as Walnut Farm, while the Silas Taylor Farm sits on Flagg Hill. Population rose quickly between 1950 and 1980, reaching 3,126, and stood at 5,506 in the 2020 census.", sources: ["https://en.wikipedia.org/wiki/Boxborough,_Massachusetts", "https://en.wikipedia.org/wiki/Boxborough_Old_Town_Center"], checked: "2026-11-17" },
  "boylston": { paragraph: "Thomas Sawyer Jr. acquired land here in 1705, and his descendants built the corn, saw, and grist mills on the Nashua River that grew into the village of Sawyer's Mills. The area became the North Precinct of Shrewsbury in 1742 and the town of Boylston in March 1786. Its hills suited orchards: by 1806 the town ran 30 cider mills, and early tax lists show more than 100 farmers. With money left by Ward Nicholas Boylston, the town built a two-story stone town hall at 7 Central Street in 1830, still in public use. The Wachusett Reservoir, built from 1895 to 1905, displaced 302 people, removed 46 dwellings, erased Sawyer's Mills and its 1855 cotton mill, and flooded the town's only rail line; it now covers about 5,000 acres of northwestern Boylston. A streetcar along Main Street from 1898 started Morningdale as a cottage suburb of Worcester, where later car-era subdivisions concentrated. The Boylston Center local historic district, created in 1979, protects 21 properties.", sources: ["https://cmrpc.org/boylston-master-plan-historical-and-cultural-chapter", "https://www.boylstonhistory.org/images/Historic Town Hall.pdf", "https://en.wikipedia.org/wiki/Boylston,_Massachusetts"], checked: "2026-11-17" },
  "braintree": { paragraph: "Captain Wollaston's 1625 outpost at Mount Wollaston is counted as Braintree's beginning, with colonists following in 1635 and incorporation in 1640. The original town was later divided to create Quincy in 1792 and Randolph in 1793. The Monatiquot River, formed where the Farm and Cochato rivers meet at the municipal golf course, runs 4.9 miles northeast to the tidal Weymouth Fore River, and its current turned grist mills and a nail mill opened by Paul Revere. In 1888 Braintree and South Braintree were still separate villages within the town. The oldest house open to visitors is the General Sylvanus Thayer Birthplace, a saltbox built by Nathaniel Thayer in 1720, enlarged in the 1760s, and moved about a mile down Washington Street in 1958 to number 786; its National Register listing dates to 1974. Population grew by more than half in the 1920s and doubled from 15,712 in 1930 to 31,069 in 1960, as families came from Boston after World War II. Great Pond, Sunset Lake and Pond Meadow Park lie within its 14.5 square miles.", sources: ["https://en.wikipedia.org/wiki/Braintree,_Massachusetts", "https://en.wikipedia.org/wiki/Monatiquot_River", "https://en.wikipedia.org/wiki/General_Sylvanus_Thayer_Birthplace"], checked: "2026-11-17" },
  "brookline": { paragraph: "Known first as Muddy River, a hamlet of Boston settled in 1638, Brookline separated as a town in 1705 and voted in 1873 to stay out of Boston. Route 9 traces the Boston and Worcester Turnpike of 1810, and the Highland branch railroad of 1847 later became the Green Line D line. Streetcar tracks laid on Beacon Street in 1888 and electrified the next year turned the northern half into a streetcar suburb lined with large brick apartment buildings. The town then banned triple-deckers and, in 1924, limited most land to single-family houses, so many apartment blocks predate that rule. South of the D line lie suburban districts and big estates such as Larz Anderson Park, the 64-acre former Anderson property. Frederick Law Olmsted kept his office at Fairsted, 99 Warren Street, and his 1890s Emerald Necklace runs along the Muddy River. The 1767 John Goddard House on Goddard Avenue survives, and named districts include Coolidge Corner, Brookline Village, Pill Hill, Fisher Hill, Corey Hill and the Cottage Farm Historic District.", sources: ["https://en.wikipedia.org/wiki/Brookline,_Massachusetts"], checked: "2026-11-17" },
  "burlington": { paragraph: "First settled around 1641 and incorporated on February 28, 1799, Burlington spent most of its history as farm country selling hops, rye, cured hams, milk and produce to Boston, with small shoe shops adding income. Mills ran along Vine Brook from colonial times into the late 1800s. The early railroads bypassed the town, which relied on the Middlesex Turnpike instead. That changed with Route 128: between 1955 and 1965 Burlington grew faster than any other Massachusetts town, and the census count went from 3,250 in 1950 to 21,980 in 1970. A few far older buildings remain, among them the Francis Wyman House of 1666 and the Meeting House of the Second Parish in Woburn on Lexington Street beside the Town Common. The land sits on the watersheds of the Ipswich, Mystic and Shawsheen rivers, with the Mill Pond Reservoir in the east, Greenleaf Mountain topping out at 290 feet and the 216-acre Mary Cummings Park on the Woburn line.", sources: ["https://en.wikipedia.org/wiki/Burlington,_Massachusetts"], checked: "2026-11-17" },
  "cambridge": { paragraph: "The first houses at Newe Towne went up in spring 1631, the settlement was renamed Cambridge in 1638, Harvard was founded in 1636, and city status came in 1846. Its original village grew around today's Harvard Square, where a marketplace stood beside a salt marsh that was later filled. The West Boston Bridge of 1792 cut the trip to Boston from eight miles by land, and turnpikes fed it. Between 1850 and 1900 streetcar suburbs grew along those roads: East Cambridge turned working-class and industrial, Cambridgeport filled with middle-class homes, and Mid-Cambridge kept estates near Harvard. Rail access in North Cambridge brought brickworks between Massachusetts Avenue, Concord Avenue and Alewife Brook, and Frederic Tudor cut ice on Fresh Pond. Brattle Street, once Tory Row, still carries 18th-century mansions. In 1935 to 1940 a tenement district was cleared for Newtowne Court and Washington Elms. Today the city covers 7.10 square miles along the Charles and recognizes 13 neighborhoods, from Kendall and Inman to Porter Square.", sources: ["https://en.wikipedia.org/wiki/Cambridge,_Massachusetts"], checked: "2026-11-17" },
  "canton": { paragraph: "Ponkapoag, the second Praying Town of the Massachusetts Bay Colony, was set off from Dorchester in 1657, and the surrounding land later belonged to Stoughton until Canton was incorporated from it on February 23, 1797. Four years later, in 1801, Paul Revere built the nation's first copper rolling mill here. The Canton Viaduct, completed in 1835 over the Neponset River, is one of the two oldest multiple-arch stone railroad bridges still carrying mainline trains in the country. Canton Corner, around Washington and Pleasant Streets, became a National Register historic district in 2009 and includes the David Tilden House, close to 300 years old. On Washington Street, Charles A. Platt designed a country house in 1902 for Arthur Tracy Cabot, now part of the Eleanor Cabot Bradley Estate. The town sits at the foot of Great Blue Hill; the Canton River runs through the center, linking Bolivar and Forge Ponds, and the Neponset marks the boundary with Norwood, Westwood, and Dedham. Population grew 71 percent in the 1950s, reaching 12,771 in 1960.", sources: ["https://en.wikipedia.org/wiki/Canton,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "carlisle": { paragraph: "Carlisle was pieced together from land belonging to Acton, Billerica, Chelmsford, and Concord, where English colonists first settled in 1651. It took its name from Carlisle, England, hometown of early settler James Adams, and the legislature made it a town in 1805. Ferns Country Store at 8 Lowell Street occupies a store dating to 1844, near the Old Burying Ground in the center. Carlisle stayed tiny for a long time, with just 478 residents in 1880 and 1,488 in 1960, before nearly doubling in the 1960s. Today about a quarter of the town is conservation land, including Great Brook Farm State Park and part of the Great Meadows refuge along the Concord River, and new house lots must be at least two acres.", sources: ["https://en.wikipedia.org/wiki/Carlisle,_Massachusetts"], checked: "2026-11-17" },
  "charlton": { paragraph: "Farm families began clearing Charlton in 1735, and the settlement was split off from Oxford as a district in 1755 before becoming a full town in August 1775. Agriculture dominated through the 1800s; woolen mills appeared along the local brooks around the turn of the 20th century. The oldest cluster of houses stands in the Northside Village Historic District on Stafford Road, where a 1735 tannery grew into a stagecoach stop: thirteen buildings, most older than 1850, including the 1775 Wheelock House, the 1797 Rider Tavern that hosted Lafayette, and the 1848 No. 2 Schoolhouse. Along Main Street between Mugget Hill Road and Masonic Home Road, the Charlton Center Historic District, listed in 1995, mixes Federal and Gothic Revival houses with the Shingle-style Overlook Hotel and a Colonial Revival town hall from 1905. Population jumped about 44 percent in the 1970s and another 42 percent in the 1980s. Buffumville Lake, run by the Army Corps of Engineers, is a flood-control reservoir managed together with Hodges Village Dam.", sources: ["https://en.wikipedia.org/wiki/Charlton,_Massachusetts", "https://en.wikipedia.org/wiki/Northside_Village_Historic_District", "https://en.wikipedia.org/wiki/Charlton_Center_Historic_District", "https://en.wikipedia.org/wiki/Buffumville_Lake"], checked: "2026-11-17" },
  "chelmsford": { paragraph: "Settlers from Woburn and Concord arrived in 1652, with incorporation of Chelmsford following in May 1655. Its first economy ran on lumber mills, limestone quarries and lime kilns. The Middlesex Canal of 1802 and the Middlesex Turnpike crossed the town early in the next century, and the farming district of East Chelmsford split off in the 1820s to become the mill city of Lowell. Several early houses survive: the Barrett-Byam Homestead of 1663, now the historical society's home, the 1691 Old Chelmsford Garrison House, the Hildreth-Robbins House of 1742, the 1798 Fiske House and the Oliver Hutchins House of 1820. North Town Hall dates from 1853, and the old core is recognized as the Chelmsford Center Historic District. The real building boom came after U.S. Route 3 was tied to Route 128 in the 1950s; population jumped from 9,407 in 1950 to 31,432 by 1970. Villages include North, South, West and East Chelmsford and the Westlands, with the Merrimack River on the northeast and the Concord River on the east.", sources: ["https://en.wikipedia.org/wiki/Chelmsford,_Massachusetts"], checked: "2026-11-17" },
  "clinton": { paragraph: "Brothers Erastus and Horatio Bigelow founded the Lancaster Mills in 1844, the first major mill to produce gingham, and its success led to Clinton's separation from Lancaster on March 14, 1850. The brick complex at Green and Chestnut Streets covers 29 acres, and Worcester contractor William T. Merrifield built both the mills and the adjacent tenement houses between 1844 and 1848. The Nashua River supplied the water power, and by 1890 the town was known for carpets and woven wire. Along High Street, between Union Street and Ring and Prospect Streets, the Downtown Clinton Historic District holds 31 contributing buildings put up between about 1840 and the 1920s, the older ones Italianate and the later ones mostly Colonial Revival. The 1857 Brimhall Building there received a Colonial Revival facelift in 1915. Construction of the Wachusett Dam began in 1897, and the reservoir, filled by 1908, flooded a substantial part of town. Water now covers about 21.8 percent of Clinton's 7.3 square miles.", sources: ["https://en.wikipedia.org/wiki/Lancaster_Mills", "https://en.wikipedia.org/wiki/Clinton,_Massachusetts", "https://en.wikipedia.org/wiki/Downtown_Clinton_Historic_District"], checked: "2026-11-17" },
  "concord": { paragraph: "Peter Bulkley and Simon Willard founded Concord in 1635 as the first inland colonial settlement in New England, with incorporation following on September 12 of that year. The town grew up where the Sudbury and Assabet rivers join to form the Concord River, which flows north to the Merrimack at Lowell. Monument Square, laid out in 1635, anchors the Concord Monument Square-Lexington Road Historic District, federally listed in 1977, where well-kept Georgian, Federal, and mid-19th-century revival houses line the streets; Wright's Tavern and the Ralph Waldo Emerson House inside it are National Historic Landmarks. The Georgian Old Manse on Monument Street was built in 1770 for Rev. William Emerson, with the river behind it and the Old North Bridge next door. On Lexington Road, the Alcotts sold the Wayside to Nathaniel Hawthorne in 1852 and moved into neighboring Orchard House in 1858. West Concord, the southwestern village along Route 62, has the Assabet running just south of its center. Population reached 12,517 by 1960 and 18,491 in 2020.", sources: ["https://en.wikipedia.org/wiki/Concord,_Massachusetts", "https://en.wikipedia.org/wiki/Concord_Monument_Square-Lexington_Road_Historic_District", "https://en.wikipedia.org/wiki/The_Old_Manse", "https://en.wikipedia.org/wiki/West_Concord,_Massachusetts"], checked: "2026-11-17" },
  "danvers": { paragraph: "Salem Village, permanently settled in 1636, became a district in 1752 named for Danvers Osborn and a town on June 9, 1757, despite a royal ban on new towns. Its farms gave their names to the Danvers onion and the Danvers Half-Long carrot. The railroad reached town in 1847 and horse trolleys in 1884, and shoe factories were busy in the late 1800s and early 1900s. Colonial-era sites still standing include the Rebecca Nurse Homestead, Ingersoll's Ordinary of 1670, the Judge Samuel Holten House and the General Israel Putnam House, with the Salem Village Historic District around them. Glen Magna Farms keeps the Derby Summer House on its grounds. Danvers Square lost 18 buildings in the fire of 1845, and Town Hall followed in 1855. Danvers State Hospital, open from 1878 to 1992, became apartments in 2008. Population grew from 15,720 in 1950 to 26,151 in 1970. The Porter, Crane and Waters rivers meet near the southeast corner to form the Danvers River, and the Ipswich River runs along the western line.", sources: ["https://en.wikipedia.org/wiki/Danvers,_Massachusetts"], checked: "2026-11-17" },
  "dedham": { paragraph: "Families from Roxbury and Watertown settled Dedham in 1635, and when it was incorporated the next year, the General Court rejected the settlers' preferred name, Contentment, in favor of Dedham in Essex, England. Its first borders reached Rhode Island, and 14 present-day communities were later carved from it. In 1639 residents dug Mother Brook, the first man-made canal in North America, joining the Charles and Neponset rivers; the drop between them powered a string of mills, and many families came to work in them. The Fairbanks House on East Street, dated by science to 1637, is the oldest surviving timber-frame house in the United States. Dedham became the seat of Norfolk County in 1793, and the Norfolk County Courthouse at 650 High Street anchors the Dedham Village Historic District, bounded roughly by High, Court, Washington, and School Streets. In Oakdale, Woodleigh Road holds many homes by Henry Bailey Alden, architect of the Endicott Estate rebuilt after a 1904 fire. Riverdale is an island ringed by the Charles River and Long Ditch.", sources: ["https://en.wikipedia.org/wiki/Dedham,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "douglas": { paragraph: "Originally the New Sherborn Grant, the township took its present name in 1746, when Boston physician William Douglass paid for the right to name it and offered money for free schools along with a 30-acre farm. The common and Center Cemetery were laid out that same year, and the 192-acre Old Douglas Center district, on the National Register since 2001, still radiates from them: mostly Federal and Greek Revival houses, the 1834 Greek Revival First Congregational Church, Dudley Tavern from around the 1770s, and the two-room Douglas Center School of 1921. Industry gathered in East Douglas, where forests fed woodcutting and the Douglas axe company; the E. N. Jenckes Store on Main Street traded from the 1830s until 1964 and is now a museum, and the Hayward Mill at North and Cook Streets carries its own federal listing. Much of the western side is water and woods: Whitin Reservoir covers about 400 acres, with Wallum Pond, Badluck Pond, and Douglas State Forest nearby.", sources: ["https://en.wikipedia.org/wiki/Douglas,_Massachusetts", "https://en.wikipedia.org/wiki/Old_Douglas_Center_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "dover": { paragraph: "Settlement on Dover's land is first recorded in 1640, when it still belonged to Dedham. It became Dedham's Springfield Parish in 1748, a separate district in 1784, and a full town in 1836. The town sits on the south bank of the Charles River, and it stayed small for a long time: only 656 people lived here in 1900. Among its oldest houses is the Benjamin Caryl House at 107 Dedham Street, built around 1777, restored to reflect life in the 1790s, and added to the Register in 2000. Along the river, Colonel John Jones planted the elms in 1740 that named Elm Bank, where a Neo-Georgian manor by Carrère and Hastings followed in 1907, with grounds planned by the Olmsted Brothers; the site gained Register status in 1987. Dover Center keeps the Sawin Building, dedicated in 1907 at Centre and Dedham Streets. Eleanor Raymond's 1948 Dover Sun House, among the first solar-heated houses, stood until 2010. Most residential zoning requires lots of at least one acre.", sources: ["https://en.wikipedia.org/wiki/Dover,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts", "https://en.wikipedia.org/wiki/Elm_Bank"], checked: "2026-11-17" },
  "dudley": { paragraph: "Colonial officials carved this land from Nipmuc territory in 1681, though permanent settlement waited until 1714 and incorporation until 1732, under a name honoring proprietors William and Paul Dudley. The old center is Dudley Hill, where a linear historic district follows Center Street from Dudley Hill Road down to Tanyard Road. Its houses are mostly Federal or Greek Revival, with two later Stick-style homes, set among the brick Conant Memorial Church of 1890, an Italianate Grange hall built around 1840 as a school, and Hezekiah Healy's Black Tavern from about 1803. Nichols Academy, opened in 1815, became the Nichols College campus at the district's southern end. Industry clustered lower down, on Mill Street and West Main Street, where Henry Hale Stevens built a five-story, U-shaped granite linen mill in the 1860s that ran into the 1990s. During the Civil War, local shops produced Brogan boots for the Union Army. The French River forms the Webster line, and about 4.6 percent of the town's area is water.", sources: ["https://en.wikipedia.org/wiki/Dudley,_Massachusetts", "https://en.wikipedia.org/wiki/Dudley_Hill_Historic_District", "https://en.wikipedia.org/wiki/Stevens_Linen_Works_Historic_District"], checked: "2026-11-17" },
  "fitchburg": { paragraph: "Settled in 1730 as part of Lunenburg and incorporated in 1764, Fitchburg is named for John Fitch, a member of the committee that secured the act of incorporation. Water power from the Nashua River ran mills that made machines, tools, clothing, paper and firearms, and the railroad through the city in 1844 spurred larger industry; the Burleigh Rock Drill, used to bore the Hoosac Tunnel, was built here. Much of the city's architecture is Victorian, built at the height of its mill-town prosperity. Around Monument Park, laid out in 1874 with Martin Milmore's Civil War statue, stand the 1891 brick state armory with Gothic towers, the 1903 Classical Revival post office and Elbridge Boyden's High Victorian Gothic courthouse of 1871. In Moran Square, east of Union Station, Sylvanus Sawyer built an 1860 factory at 64 Main Street and a Second Empire house that still stands at 21–23 Summer Street. Neighborhoods include Cleghorn, Crockerville, The Patch and Upper Common, and Brown Hill rises to 1,210 feet in the northwest.", sources: ["https://en.wikipedia.org/wiki/Fitchburg,_Massachusetts", "https://en.wikipedia.org/wiki/Moran_Square_Historic_District", "https://en.wikipedia.org/wiki/Monument_Park_Historic_District"], checked: "2026-11-17" },
  "foxborough": { paragraph: "Foxborough was settled in 1704 and incorporated in 1778, taking its name from Charles James Fox. Straw hats were its signature trade: the world's largest straw hat factory went up here in 1886, later held a boot and shoe company and then the Inman and Kimball hat works, and burned in 1936; the post office stands on that site now. Several older houses carry National Register listings, among them the Ezra Carpenter House at 168 South Street, the Otis Cary House at 242 South Street, and the Seth Boyden House at 135 Oak Street. In the town center, stone-built Memorial Hall once held the library, and the Foxboro Grange Hall on Bird Street was listed in 1983. The former Foxborough State Hospital, at Chestnut and Main Streets, joined the Register in 1994. Population climbed from 7,030 in 1950 to 14,218 in 1970, around the time Schaefer Stadium opened in 1971. Outlying sections include Quaker Hill in South Foxborough and Foxvale, and the F. Gilbert Hills State Forest covers 1,027 acres shared with Wrentham.", sources: ["https://en.wikipedia.org/wiki/Foxborough,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "framingham": { paragraph: "John Stone started the first English farm here on the west bank of the Sudbury River in 1647, and Thomas Danforth later gathered more than 15,000 acres; Framingham was incorporated in 1700, the year after his death. The early center survives in the Framingham Centre Common Historic District, whose 28 buildings include the Village Hall, First Parish Church and the former Framingham Academy. Saxonville grew as a mill village where the Roxbury Carpet Company rebuilt its brick and concrete mills after fires in the 1880s, and some of its mill worker housing dates to the 1820s. South Framingham became the commercial center after the railroad arrived, home to Dennison Manufacturing, and most buildings in its Concord Square Historic District date from 1890 to 1920. After World War II, much of the new housing took the form of split-level and ranch houses. The Sudbury Aqueduct begins at Farm Pond, and the dams and gatehouses of Framingham Reservoirs No. 1, 2 and 3 are on the National Register. Framingham became a city in 2018.", sources: ["https://en.wikipedia.org/wiki/Framingham,_Massachusetts", "https://en.wikipedia.org/wiki/Framingham_Centre_Common_Historic_District", "https://en.wikipedia.org/wiki/Saxonville_Historic_District", "https://en.wikipedia.org/wiki/Concord_Square_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Framingham,_Massachusetts"], checked: "2026-11-17" },
  "franklin": { paragraph: "Formed from the western part of Wrentham and incorporated on March 2, 1778, after European settlement began in 1660, Franklin was the first municipality in the country named for Benjamin Franklin. Instead of a church bell, Franklin donated 116 books, and the free lending library the town set up in 1790 still operates; its Ray Memorial Library building was dedicated in 1904. The Franklin Common Historic District centers on a roughly triangular green that took shape in the mid-18th century and extends up Main Street to Lincoln Street, site of the Red Brick School, a building from 1833 that held classes until 2008. Houses make up most of the district, with the 1895 Shingle-style Federated Church and the St. Mary's Church complex facing the common, and the Dean Junior College Historic District adjoins it to the south. Horace Mann was born in the town. Most of Franklin drains to the Charles River through Mine, Shepard's, Miller, Uncas, Dix and Miscoe Brooks, and the marshes along Mine Brook are permanently protected for flood storage.", sources: ["https://en.wikipedia.org/wiki/Franklin,_Massachusetts", "https://en.wikipedia.org/wiki/Franklin_Common_Historic_District"], checked: "2026-11-17" },
  "grafton": { paragraph: "Hassanamesit, a Nipmuc praying town founded in 1647, preceded English Grafton; in 1727 its 8,000-acre reservation was split, with 7,500 acres going to 40 English proprietors, and Grafton became a town in 1735. A small piece survives as the Hassanamisco Reservation on Brigham Hill Road, listed on the National Register in 2011. The oval common dates from 1728 and got its fence in 1845, and because the railroads bypassed it, the surrounding district kept its mostly mid-19th-century buildings, including the Federal-style Grafton Inn of 1805, the 1833 Greek Revival Congregational Church, and the Italianate Unitarian Church of 1863. Manufacturing went instead to the mill villages: Farnumsville and Fisherville both became historic districts in 1996, and North Grafton's Upper Mill, later Washington Mills, began in 1826. Grafton State Hospital operated in North Grafton from 1901 to 1973, and its grounds now hold the Tufts veterinary school. Population more than doubled from 8,281 in 1950 to 19,664 in 2020.", sources: ["https://en.wikipedia.org/wiki/Grafton,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts", "https://en.wikipedia.org/wiki/Grafton_Common_Historic_District"], checked: "2026-11-17" },
  "groton": { paragraph: "Settled and incorporated in 1655, Groton once covered present-day Ayer and nearly all of Pepperell and Shirley. King Philip's War reached the town on March 13, 1676, when raiders burned every building except four garrison houses; survivors fled to Concord, and many returned two years later. Agriculture carried the economy, helped by the Nashua and Squannacook rivers, while the Hollingsworth family ran a paper mill in West Groton from the early 1800s and a soapstone quarry found in 1828 worked until 1868. Two schools shaped the center: Lawrence Academy, founded in 1793 as Groton Academy, and Groton School, founded in 1884. On Main Street, the former Groton High School at No. 145 holds an individual Register listing. When the old hospital on Main Street was demolished for a supermarket, the town responded by creating the Groton Center Historic District in 1964 and enlarging it in 1965; its commission reviews any facade change visible from the district. At 33.7 square miles, Groton is the largest town by area in Middlesex County, and Gibbet Hill rises over its center.", sources: ["https://en.wikipedia.org/wiki/Groton,_Massachusetts", "https://www.grotonma.gov/?p=391"], checked: "2026-11-17" },
  "harvard": { paragraph: "Harvard was incorporated in 1732 from parts of Lancaster, Groton and Stow, along a road between Lancaster and Groton laid out in 1658; by 1734 it counted five villages: Oak Hill, Bare Hill, Still River, Old Mill and Shabikin, now Devens. Agriculture drove the economy until the middle of the 20th century, and apple orchards remain common. The town common, laid out in 1732 and bounded by Elm Street, Still River Road and Ayer Road, anchors the Harvard Center Historic District, about 125 acres with 59 significant houses, most of its buildings dating after 1831. Civic buildings there include a stone animal pound, a powder house, the 1872 Gothic Revival town hall, an 1828 Greek Revival former town hall and the Romanesque Bromfield School of 1878. Along Shaker Road, South Shaker Road and Maple Lane, the Harvard Shaker Village Historic District preserves buildings of a community that peaked at about 200 members in the 1850s; most are now privately owned. Fruitlands, Bronson Alcott's 1843 farm experiment on Prospect Hill, is now a museum.", sources: ["https://en.wikipedia.org/wiki/Harvard,_Massachusetts", "https://en.wikipedia.org/wiki/Harvard_Center_Historic_District"], checked: "2026-11-17" },
  "holden": { paragraph: "Settled in 1723 and incorporated in 1741, Holden takes its name from Samuel Holden, a director of the Bank of England. Its center, a National Register district since 1977 and enlarged in 1995 to take in surrounding residential streets, holds the 1759 Old Burying Ground, the 1789 First Congregational Church, the 1835 First Baptist Church, the 1836 town hall, and an 1880 post office, with Greek Revival as one of the main styles. Mill work centered in the northwest: in Eagleville, now part of Jefferson village along Main, Princeton, and High Streets, a dam and mill complex built around 1850 still stand beside substantial blocks of mill worker housing, listed in 2010. Several farmhouses were added to the Register individually in 1995 and 1996, including the Brown-Davis-Frost Farm on Whitney Street and Stony Farm and Paddock Farm on Salisbury Street. The Quinapoxet River crosses the hilly landscape. Holden's growth came late: 5,975 residents in 1950, 10,117 by 1960, and 19,905 in 2020.", sources: ["https://en.wikipedia.org/wiki/Holden,_Massachusetts", "https://en.wikipedia.org/wiki/Holden_Center_Historic_District", "https://en.wikipedia.org/wiki/Eagleville_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "holliston": { paragraph: "Settlers following Pout Lane, a Native footpath that is now partly Route 16 and Highland Street, formed the cluster of farms that became Holliston. The area, then part of Sherborn, was first settled by Europeans in 1659 and incorporated on December 3, 1724, named for Thomas Hollis of London. Washington Street was laid out in 1731 toward Mendon, and the Thomas Hollis Historic District follows it for about a mile between Winter and Highland Streets. Growth before the Civil War produced that street's houses in Federal and Greek Revival styles, along with the 1822 First Congregational Church, plus the 1855 Italianate Town Hall; the Isaac Foster House at 617 Washington Street dates to 1727. Brick commercial buildings followed the railroad around 1900. In East Holliston, Jarr Brook drew late 18th- and early 19th-century industry and a group of Greek Revival houses along Washington and Curve Streets, where building largely stopped around 1870. The Goodwill Shoe Company's former factories on Water Street, many now artists' studios, recall the town's shoe industry.", sources: ["https://en.wikipedia.org/wiki/Holliston,_Massachusetts", "https://en.wikipedia.org/wiki/Thomas_Hollis_Historic_District", "https://en.wikipedia.org/wiki/East_Holliston_Historic_District"], checked: "2026-11-17" },
  "hopedale": { paragraph: "Benjamin Albee built a mill at the south end of present-day Hopedale in 1664, but the name dates from August 1841, when Adin Ballou's Practical Christians chose it for a settlement inside Milford. Their utopian Hopedale Community, founded in 1842, went bankrupt in 1856, and George and Ebenezer Draper bought its assets; the Draper loom business eventually became the largest U.S. maker of textile looms. Hopedale split from Milford as its own town in 1886, and George Draper designed and financed its 1887 town hall. The company housed its workers in double houses: the duplexes on Dutcher Street, built between 1902 and 1907, were roomier than typical mill housing, kept up by the company, and fenceless by rule, and by 1910 every home had water, gas, electricity, and indoor plumbing. The 804-acre Hopedale Village Historic District, listed in 2002, covers the mill site at Hopedale and Freedom Streets, those housing streets, and the mill pond. Olmsted's firm designed the 275-acre Parklands around Hopedale Pond in 1899.", sources: ["https://en.wikipedia.org/wiki/Hopedale,_Massachusetts", "https://www.nps.gov/places/hopedale-company-housing.htm", "https://en.wikipedia.org/wiki/Hopedale_Village_Historic_District"], checked: "2026-11-17" },
  "hopkinton": { paragraph: "Incorporated on December 13, 1715, Hopkinton grew on 12,500 acres that Harvard's trustees bought with a bequest from the Connecticut colonist Edward Hopkins. Grain, fruit and dairy farming dominated until boot and shoe making arrived in 1840; eleven factories were running by 1850, but fires in 1882 and the industry's move elsewhere ended that era. Former factory worker housing still stands in the center of town. The local Hopkinton Center Historic District covers 23 properties around the Town Common, on East Main Street and the south side of Main Street. Woodville, in the western part of town at the north end of Whitehall Reservoir, became a second historic district in 2005, with 97 properties tied to mid-to-late 19th-century cotton and shoe manufacturing. At 26–28 Main Street, a 1906 pressed-metal storefront made by the George L. Mesker Company of Evansville, Indiana, holds a National Register listing. Hopkinton Reservoir, North Pond and Echo Lake also lie within the town's 27.9 square miles.", sources: ["https://en.wikipedia.org/wiki/Hopkinton,_Massachusetts", "https://en.wikipedia.org/wiki/Hopkinton_Supply_Co._Building"], checked: "2026-11-17" },
  "hudson": { paragraph: "Until 1866, Hudson was Feltonville, a village of Marlborough named for Silas Felton, who arrived in 1799. John Barnes built a gristmill on the Assabet River around 1698, and Daniel Stratton's shoe shop of 1816 grew into a small Washington Street factory by 1821. Railroads arrived in the 1850s, and by 1860 the village had 17 shoe and shoe-related factories that drew Irish and French Canadian workers; the last shoe factory burned in 1968. Most residents lived in modest houses with small backyard gardens, while wealthier citizens built Queen Anne houses such as the Colonel Adelbert Mossman House at 76 Park Street, completed by 1903. The Goodale Homestead on Chestnut Street, a timber-frame house whose oldest part dates to 1702, is the town's oldest building. On July 4, 1894, a fire destroyed 40 buildings across 5 acres of the center, which was rebuilt within a year or two. By 1900 the town had a power plant on Cherry Street, and it still produces its own electricity through the Hudson Light and Power Department.", sources: ["https://en.wikipedia.org/wiki/Hudson,_Massachusetts", "https://en.wikipedia.org/wiki/Colonel_Adelbert_Mossman_House", "https://en.wikipedia.org/wiki/Goodale_Homestead"], checked: "2026-11-17" },
  "lancaster": { paragraph: "Incorporated in 1653 after settlement as Nashaway in 1643, Lancaster is the oldest town in Worcester County, and Harvard, Bolton, Leominster, Clinton, Berlin and Sterling were all formed from its original territory. Its center runs about 0.8 miles along Main Street, Route 70, on a north-south ridge inside a bend of the Nashua River. No 17th-century buildings survive in the Center Village District, but it keeps a few 18th-century houses and many 19th-century ones, almost all wood-frame and 1½ to 2½ stories tall. Charles Bulfinch's First Church of Christ, completed in 1816, carries National Historic Landmark status; the 1908 Colonial Revival town hall, the 1868 Thayer Library and the 1904 Center School share its common. The 1830 Joseph Andrews House has a two-story Greek Revival temple front. On North Main Street, the North Village Historic District holds 22 clapboarded buildings, only three of them built after the 19th century, including the house John Bennett built in 1717. The village of South Lancaster also lies within the town.", sources: ["https://en.wikipedia.org/wiki/Lancaster,_Massachusetts", "https://en.wikipedia.org/wiki/Center_Village_District", "https://en.wikipedia.org/wiki/North_Village_Historic_District"], checked: "2026-11-17" },
  "leicester": { paragraph: "Proprietors who bought this upland in 1686 called it Strawberry Hill, and the General Court incorporated the town in 1714 on condition that 50 families settle within seven years. Its mills specialized in card clothing, the toothed tools that straighten fiber before spinning: they turned out a third of American hand cards in the 1780s, and Pliny Earle built the carding machine used in Samuel Slater's first mill in Pawtucket. Housing grew in four villages, Leicester Center, Cherry Valley on the Worcester side, Rochdale near the Oxford line, and Greenville, whose Baptist church was organized in 1737. Water-supply reservoirs on Kettle Brook later replaced the former hamlets of Mannville and Lakeside. Washburn Square, the town common, anchors a 21-acre historic area, federally listed in 2006, with the 1834 Unitarian church, a 1901 Gothic Revival Congregational church, the 1939 town hall, and a row of large houses on the south side. Milestones set in 1767 still mark the old Upper Boston Post Road. Population rose from 6,029 in 1950 to 9,140 in 1970.", sources: ["https://en.wikipedia.org/wiki/Leicester,_Massachusetts", "https://en.wikipedia.org/wiki/Washburn_Square-Leicester_Common_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "leominster": { paragraph: "Leominster was part of Lancaster from 1653 and became its own town on June 23, 1740. The Fifth Massachusetts Turnpike, opened around 1800, made it a regional crossroads, but manufacturing took off with the Fitchburg Railroad through North Leominster and the Fitchburg and Worcester Railroad through the center. By the 1850s, paper mills, piano makers and comb factories lined Monoosnoc Brook and the Nashua River, and in 1853 there were 24 comb factories. Celluloid, invented in 1868, and later injection molding at Foster Grant earned it the name Pioneer Plastics City. Population rose from 2,069 in 1840 to 19,744 in 1920 as Irish, French Canadian and Italian workers arrived, and Leominster became a city in 1915. The F. A. Whitney Carriage Company complex off Water Street, whose oldest buildings date to 1872, has mostly been converted to housing. The Monument Square Historic District, at Main and Water Streets and Grove Avenue, keeps the common chosen in 1743 for the First Church meeting house and many 19th-century buildings.", sources: ["https://en.wikipedia.org/wiki/Leominster,_Massachusetts", "https://en.wikipedia.org/wiki/F._A._Whitney_Carriage_Company_Complex_Historic_District", "https://en.wikipedia.org/wiki/Monument_Square_Historic_District_(Leominster,_Massachusetts)"], checked: "2026-11-17" },
  "lexington": { paragraph: "Europeans settled here around 1642 as part of Cambridge, the area became the separate parish of Cambridge Farms in 1691, and it was incorporated as Lexington in 1713. Several colonial buildings still stand: Munroe Tavern from about 1695, Buckman Tavern from roughly 1704 to 1710, and the Hancock-Clarke House of 1737, while stones in the Old Burying Ground go back to 1690. Follen Church, built in 1839, is the oldest church building standing in town. For generations after the Revolution, Lexington remained a farm town sending produce to Boston, with Vine Brook powering mills and later irrigation, and rail service ran from 1846 until 1981. The Route 128 technology boom brought rapid growth in the 1960s and 1970s, and by the 1970s many farms had become subdivisions. That era also produced modernist neighborhoods such as Six Moon Hill, Five Fields, and Peacock Farm, the last designed by Walter Pierce and built from 1952 to 1958, which is on the National Register. Population peaked at 31,886 in 1970.", sources: ["https://en.wikipedia.org/wiki/Lexington,_Massachusetts"], checked: "2026-11-17" },
  "lincoln": { paragraph: "Europeans settled Lincoln in 1654 as the southeast corner of Concord. In 1754 it split off as its own town, assembled mostly from Concord with slices of Weston and Lexington, which earned it the nickname Niptown; Chambers Russell, who pushed for the new town, named it after his family's home in Lincolnshire, England. Russell's homestead later passed to the Codman family and survives as the Codman House. Paul Revere was captured within Lincoln's bounds on the night of April 18, 1775, and Hartwell Tavern and the Hunt-Rice Tavern survive among the town's landmarks. The town's other landmark era came in 1938, when Walter Gropius and Marcel Breuer completed the Gropius House at 68 Baker Bridge Road, a balloon-framed house sheathed in vertical white-painted redwood that Gropius said absorbed New England traditions. Four more 1930s modernist houses on Woods End Road form a historic district designated in 1988. Most land remains zoned for residential and agricultural use. Between 1950 and 1960 the count climbed from 2,427 to 5,613.", sources: ["https://en.wikipedia.org/wiki/Lincoln,_Massachusetts", "https://en.wikipedia.org/wiki/Gropius_House"], checked: "2026-11-17" },
  "littleton": { paragraph: "In 1645 John Eliot founded Nashoba Plantation, the sixth Praying Indian village, on land between Lake Nagog and Fort Pond. English settlement followed in 1686, and Littleton gained incorporation in 1715, the same year a meetinghouse rose on the Foster Street lot now occupied by First Church Unitarian. Several colonial buildings remain, including the Long Store on Great Road and the Fox Tavern at 35 Foster Street, both from around 1700, and the Lawrence (Hartwell) Tavern of 1768 on Crane Road. Apple orchards and cider made the town's name in the 1800s, and the Fitchburg Railroad arrived in 1844, with a station built in 1879 that served until 1970. Near the Common, the Conant Houghton mill was erected in 1880, and the Houghton Memorial Building went up in 1894 and 1895 to house the library. Families from Boston-area cities moved in during the 1950s and 1960s, more than doubling the population to 5,109 by 1960. Mill Pond, also called Lake Warren, and Long Lake shape the neighborhoods around them.", sources: ["https://en.wikipedia.org/wiki/Littleton,_Massachusetts"], checked: "2026-11-17" },
  "lunenburg": { paragraph: "Europeans settled Lunenburg in 1718, and it was incorporated in 1728 under a name drawn from a title of King George II. Land that later became part of Fitchburg broke away around 1764. Lacking good water power and strong rail connections, the town was passed over by industry and remained a rural farming community until World War I. Its civic center was laid out on Turkey Hill, close to the town's geographic middle. That center now forms the Lunenburg Historic District, recognized federally in 1988 and covering 102 acres along Main Street, Massachusetts Avenue (Route 2A), Leominster Road, Lancaster Avenue, and Highland Street. Most of its 77 historic buildings are wood-frame houses, with Greek Revival and Federal designs well represented; among the oldest are the Cushing House of about 1724 and the Stillman Stone House of about 1730. Town offices occupy a former Greek Revival Unitarian church, and a brick district schoolhouse survives from 1835. On Whalom Lake, the Whalom Park amusement grounds operated until 2000. Population jumped in the 1950s and 1960s and reached 11,782 in 2020.", sources: ["https://en.wikipedia.org/wiki/Lunenburg,_Massachusetts", "https://en.wikipedia.org/wiki/Lunenburg_Historic_District"], checked: "2026-11-17" },
  "lynn": { paragraph: "Edmund Ingalls led the first settlers here in 1629, the name Lynn came in 1637, and the city charter followed on May 14, 1850. Tanning and shoemaking began around 1635, the Eastern Railroad opened through town in 1838, and by the early 1900s Lynn had 234 shoe factories; the last one closed in 1981. Shoe money also helped start the Thomson-Houston Electric Company in 1883, which became one of General Electric's two original plants. Fire has repeatedly reshaped downtown: 296 buildings burned in 1889, and 17 former shoe factories near Broad and Washington Streets were lost in 1981. Three National Register districts cover older fabric: the Central Square district downtown, the Lynn Common district between North and South Common Streets, and the Diamond Historic District by the sea, with mid-19th-century beach cottages and buildings tied to Lynn Shore Drive, opened in 1910. Old factory buildings such as the Flatiron Building are being turned into lofts. Lynn Woods, about 2,200 acres, covers more than a quarter of the city, and Nahant splits the shore into Lynn Harbor and Nahant Bay.", sources: ["https://en.wikipedia.org/wiki/Lynn,_Massachusetts"], checked: "2026-11-17" },
  "malden": { paragraph: "Puritans settled the \"Mistick Side\" of Charlestown in 1640, and gained incorporation in 1649 under the spelling Mauldon. Melrose split off in 1850 and Everett in 1870, and Malden became a city in 1882. The fastest growth came between 1880 and 1900, when population nearly tripled from 12,017 to 33,664. Maplewood shows how that growth was planned: in 1847 Joshua Webster bought about 200 acres along the coming Saugus Branch Railroad and laid out wide streets lined with the maples that gave the neighborhood its name. At the foot of Pearl Street in Edgeworth stood the Converse Rubber factory, and Elisha S. Converse, the first mayor, paid for the Converse Memorial Library, built in 1885 to a design by Henry Hobson Richardson. Bell Rock Cemetery holds marked graves from 1670 and, with Bell Rock Memorial Park, carries a National Register listing. The old Saugus Branch right-of-way is now the Northern Strand Trail. The Malden River drains the city, and the land rises to Boojum Rock, about 275 feet, in the Middlesex Fells on the northwest edge.", sources: ["https://en.wikipedia.org/wiki/Malden,_Massachusetts"], checked: "2026-11-17" },
  "marlborough": { paragraph: "Families from Sudbury led by Edmund Rice and John Howe petitioned for a new town in 1656, and Marlborough was incorporated in 1660 where the Nashua Trail met the Connecticut Path. Its inns on the Boston Post Road served travelers, among them George Washington at the Williams Tavern in 1789. Samuel and Joseph Boyd opened the first shoe business in 1836, and by 1890, when Marlborough became a city, its 14,000 residents lived in a major shoe center. The Marlborough Center Historic District along Main Street, between Mechanic and Bolton Streets, holds mostly brick and stone commercial blocks of the late 19th and early 20th centuries and the 1905 Beaux-Arts City Hall. West of downtown, the West Main Street Historic District has 77 properties, mostly houses built from 1820 to 1930, including the Greek Revival William Pitt Brigham House of about 1858 on Pleasant Street. Skilled workers built larger houses on Witherbee and Winthrop Streets, and many have since been split into multiple units. Interstates 495 and 290 and the Massachusetts Turnpike later brought high-technology employers.", sources: ["https://en.wikipedia.org/wiki/Marlborough,_Massachusetts", "https://en.wikipedia.org/wiki/Marlborough_Center_Historic_District", "https://en.wikipedia.org/wiki/West_Main_Street_Historic_District_(Marlborough,_Massachusetts)"], checked: "2026-11-17" },
  "maynard": { paragraph: "Before 1871, the place now called Maynard was Assabet Village, split between Stow and Sudbury; that year it became its own town, buying its way out with about $23,600 to Sudbury and $8,000 to Stow. The village existed because of the Assabet River, where Amory Maynard and William Knight built a dam and woolen mill in 1846 and 1847. The American Woolen Company bought the mill in 1899 and enlarged it through 1919, and Digital Equipment Corporation filled the complex from 1957 to 1998. Mill growth produced New Village, now called the Presidential district: 206 worker houses built in 1902 and 1903, plus 50 more in 1918, on streets such as Arthur, Cleveland, Garfield, and McKinley. Those homes were rented until many were auctioned in 1934. Older fabric survives too, including the Silas Brooks house of about 1764 at 88-90 Summer Street. The town covers only about 5.4 square miles, with Summer Hill at 358 feet and the Assabet crossed by seven road bridges.", sources: ["https://en.wikipedia.org/wiki/Maynard,_Massachusetts"], checked: "2026-11-17" },
  "medfield": { paragraph: "Dedham men laid out Medfield, first called New Dedham, in 1649, and the first 13 house lots were drawn on June 19, 1650. Release from Dedham came in 1651, making it the 43rd town in Massachusetts. In 1676, during King Philip's War, much of the settlement burned, including two mills and the Peak House, which was rebuilt in 1680 with the steepest roof pitch recorded on a 17th-century Massachusetts house. The Dwight-Derby House followed in 1697, and tree-ring dating places parts of the Lowell Mason house at 1651; that First Period house was moved to Green Street in 2011. Medfield State Hospital opened on 685 acres in 1896 and closed in 2003, and the town bought 128 acres of its grounds in 2014. The Charles River runs along nearly a third of the town's edge, forming the Millis line, while Noon Hill rises to 370 feet. Population climbed 63 percent in the 1960s, from 6,021 to 9,821.", sources: ["https://en.wikipedia.org/wiki/Medfield,_Massachusetts"], checked: "2026-11-17" },
  "medford": { paragraph: "Settled in 1630 as part of Charlestown, Medford grew up along the Mystic River, which still runs through the middle of the city. Matthew Cradock's plantation occupied the north bank from 1634, and a toll bridge built in 1637 at today's Cradock Bridge was the only Mystic crossing until 1787. Yards such as Hayden & Cudworth launched clipper ships, and local works turned out brick, tile, crackers and rum. The Lowell line reached West Medford in the 1830s and the Boston & Maine came to Medford Center in 1847; after the 1840s and 1850s old farms were subdivided for homes, and trolleys arrived in the late 1890s. Population climbed from 18,244 in 1900 to 66,113 in 1950. Colonial survivors include the Royall House and Slave Quarters, a National Historic Landmark, and the brick Peter Tufts House at 350 Riverside Avenue, while the Old Ship Street Historic District keeps a cluster of older homes. Neighborhoods range from West Medford and its Brooks Estates to South Medford, Wellington and the Hillside near Tufts University.", sources: ["https://en.wikipedia.org/wiki/Medford,_Massachusetts"], checked: "2026-11-17" },
  "medway": { paragraph: "Water power from the Charles River and Chicken Brook turned Medway, first settled in 1657 and incorporated on October 25, 1713, from a farming community of 233 people into a place of cotton and paper mills and straw and boot factories. Until 1885 the town also included East Medway, now Millis, which the Great Black Swamp separated from the western settlement. Village Street, laid out in 1670 as Old Mendon Road, follows the river from the Millis line toward Bellingham, and Medway Village grew where Holliston Street meets it. The Medway Village Historic District covers 60 acres and more than 240 structures, most built between 1831 and 1897; a rail station there operated from 1861 to 1966. In West Medway, the Rabbit Hill Historic District, about 40 acres bounded roughly by Highland, Main, Franklin and Milford Streets, grew around the Second Congregational Church and consists largely of Federal and Greek Revival homes. All of the town's streets received official names in 1869.", sources: ["https://en.wikipedia.org/wiki/Medway,_Massachusetts", "https://en.wikipedia.org/wiki/Medway_Village_Historic_District", "https://en.wikipedia.org/wiki/Rabbit_Hill_Historic_District"], checked: "2026-11-17" },
  "melrose": { paragraph: "Richard and Ralph Sprague explored this ground in 1628, and for two centuries it was North Malden, the upland end of Malden. It separated as the town of Melrose in 1850, annexed the Melrose Highlands from Stoneham in 1853 to fix its present borders, and became the state's 33rd city in 1899. The railroad set the pattern: by 1845 the Boston and Maine stopped at three places now called Wyoming Hill, Melrose/Cedar Park and Melrose Highlands, and Boston workers moved out for a country setting. Farmland was cut into house and business lots through the later 1800s, and Town Hall went up in 1873. Downtown Melrose joined the National Register on April 1, 1982, and the public library followed in 1988. Population peaked at 33,180 in 1970. Ell Pond sits near the center, Swains and Towners ponds lie on the East Side near Mount Hood, and the eastern edge of the Middlesex Fells reaches into the city alongside Sewall Woods and Pine Banks Park.", sources: ["https://en.wikipedia.org/wiki/Melrose,_Massachusetts"], checked: "2026-11-17" },
  "mendon": { paragraph: "Braintree pioneers moved here after a 1662 deed with Native leaders, and Mendon was incorporated on May 15, 1667, as a 64-square-mile township that once included at least part of Milford, Bellingham, Hopedale, Uxbridge, Upton, Blackstone, Northbridge, and Millville. King Philip's War hit in July 1675 with deaths and the loss of Albee's mill, and the town was largely burned in early 1676. Founders' Park, at the junction of Main, Hastings, North, and Milford Streets, marks the original center and first meeting house. Around it, the 400-acre Mendon Center district, recognized in 2003, keeps houses from the 18th century to the mid-20th century in Colonial, Federal, and other styles, focused on the 1820 Second Unitarian Church designed by Elias Carter. North of the village, the 345-acre North Avenue Rural Historic District preserves farmland worked since the 17th century, mostly 19th-century buildings, and the Federal-style Seth Davenport house of about 1780. Lake Nipmuc drew early-20th-century crowds to a resort park with vaudeville acts.", sources: ["https://en.wikipedia.org/wiki/Mendon,_Massachusetts", "https://en.wikipedia.org/wiki/Mendon_Center_Historic_District", "https://en.wikipedia.org/wiki/North_Avenue_Rural_Historic_District"], checked: "2026-11-17" },
  "milford": { paragraph: "Milford pink granite, discovered here in 1870, kept local quarries working until about 1940 and was used in Memorial Hall, Worcester City Hall and the Boston Public Library. The land was first settled in 1662 as part of Mendon, destroyed during King Philip's War in 1676 and resettled in 1680. Its name comes from the fords of the Mill River, and incorporation followed on April 11, 1780. Thomas Silloway designed the town hall built in 1854. The Mill River, the nearby headwaters of the Charles and the Blackstone River watershed helped make Milford an industrial and quarrying town in the 19th century. The Prospect Heights Historic District, roughly bounded by Prospect Heights, Prospect and Water Streets, preserves a neighborhood the Draper Corporation of Hopedale created for its immigrant workers; the federal register added it in 1990. Interstate 495 and Routes 16, 85, 109 and 140 all cross the town's 14.9 square miles, which drain to the Charles River.", sources: ["https://en.wikipedia.org/wiki/Milford,_Massachusetts", "https://en.wikipedia.org/wiki/Prospect_Heights_Historic_District_(Milford,_Massachusetts)"], checked: "2026-11-17" },
  "millbury": { paragraph: "Until June 1813, Millbury was the North Parish of Sutton, first settled in 1716; residents petitioned for a separate town named for its mills. John Singletary was running a mill on Singletary Brook, the outlet of Singletary Lake, by 1735. The Blackstone River drove the bigger works: Asa Waters and his brother Elijah built mills along it and opened an armory in 1808, which closed in 1841 and restarted in 1861 for the Civil War. Asa's own house, the Asa Waters Mansion at 123 Elm Street, is a three-story Federal frame designed by Asher Benjamin, begun in 1826 and finished in 1832, with two-story fluted columns across the front; it now houses the Millbury Historical Society. Remnants of the Blackstone Canal in town fall within a multi-town canal district recognized in 1995, and the First Presbyterian Society Meeting House at 20 Main Street was listed in 2010. Residents numbered 3,081 in 1850 and 13,831 in 2020.", sources: ["https://en.wikipedia.org/wiki/Millbury,_Massachusetts", "https://en.wikipedia.org/wiki/Asa_Waters_Mansion", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "millis": { paragraph: "For more than a century and a half Millis was East Medway, cut off from the rest of Medway by the Great Black Swamp, until railroad entrepreneur Lansing Millis secured its incorporation on February 24, 1885. The Hartford and Dedham Turnpike, now Route 109 and Main Street, was built in the early 1800s, and the railroad came through in the 1850s. The town stayed agrarian until reliable rail service arrived in the 1880s, when Lansing Millis opened a shoe factory, a steel factory and a bottling plant. Clicquot Club ginger ale was made on Main Street and gave its name to the village of Clicquot, and the Herman Shoe Company factory was demolished in March 2020. Clay dug along Causeway Street was turned into bricks for estates and buildings in the area. The Millis Center Historic District covers 110 acres along Main, Exchange, Curve and Union Streets, and most of its buildings postdate 1850; the oldest house, John Richardson's mid-18th-century Georgian colonial, stands at 191 Curve Street.", sources: ["https://en.wikipedia.org/wiki/Millis,_Massachusetts", "https://en.wikipedia.org/wiki/Medway,_Massachusetts", "https://en.wikipedia.org/wiki/Millis_Center_Historic_District"], checked: "2026-11-17" },
  "milton": { paragraph: "Industry in Milton began at the Neponset River falls, where Israel Stoughton's 1634 grist mill gave Lower Mills its name. The area was settled in 1640 as part of Dorchester and was set off as Milton in 1662. A powder mill followed in 1674, New England's first paper mill opened on the river in 1729, and Walter Baker began making chocolate in a converted grist mill in 1764. In 1826 the Granite Railway started hauling Quincy stone to a Milton wharf, and the settlement it created, once called Railway Village, is now East Milton Square. Boston families built summer estates on Milton Hill and Brush Hill; the Greek Revival Captain Robert Bennet Forbes House of 1833 still stands at 215 Adams Street. The Suffolk Resolves House was moved from Lower Mills to 1370 Canton Avenue, and the 1777 Governor Belcher House sits in East Milton. Many estates were subdivided by the 1950s, and about 78 percent of homes are single-family. The hilly town lies between the Neponset on the north and the Blue Hills on the south.", sources: ["https://en.wikipedia.org/wiki/Milton,_Massachusetts"], checked: "2026-11-17" },
  "natick": { paragraph: "John Eliot founded Natick in 1651 as the first of his Praying Indian towns, along the Charles River in present-day South Natick. The John Eliot Historic District there, at the junction of Eliot, Union and Pleasant Streets, shows architecture from the 18th to early 20th centuries laid out along 17th-century routes; the village's first dam was built in 1752. Incorporation came in 1781, and today's center grew after a meeting house went up in 1799 and rails of the Boston and Worcester line arrived in 1835. Shoe factories followed the sewing machine, and by 1880 Natick's 23 factories made it third in the nation for shoe output, much of it heavy brogans. An 1874 fire destroyed 18 business blocks, the Town Hall and many homes, and the brick Gothic and Romanesque buildings of the Natick Center Historic District replaced them; the 1875 Central Fire Station on Summer Street now houses an arts center. The H. Harwood & Sons baseball factory became condominiums in 1988. Lake Cochituate and Dug Pond hold most of the town's water area.", sources: ["https://en.wikipedia.org/wiki/Natick,_Massachusetts", "https://en.wikipedia.org/wiki/John_Eliot_Historic_District", "https://en.wikipedia.org/wiki/Natick_Center_Historic_District"], checked: "2026-11-17" },
  "needham": { paragraph: "In 1680 a tract of roughly four by five miles was bought from Chief Nehoiden, and about 40 men living north of the Charles River later petitioned to leave Dedham's North Parish, citing poor schools and churches. The General Court incorporated Needham in 1711, naming it for Needham Market in England. A western parish, organized after fire destroyed the meetinghouse in 1774, broke away as Wellesley in 1881. Beginning in 1857, Goss and Munson ran trains over six miles of track, 16 trips a day, carrying Needham fill to build Boston's Back Bay. William Carter opened a knitting mill in Needham Heights in 1865, and his company ran seven mills by the 1960s; Avery Manor now stands on the site of Carter Mill No. 1. The Town Hall, dedicated in 1903, anchors the Needham Town Hall Historic District on Great Plain Avenue between Highland Avenue and Chapel Street. The Charles River forms almost all of the town's southern and northeastern edges, and Echo Bridge spans it. Population rose 58 percent in the 1950s, to 25,793.", sources: ["https://en.wikipedia.org/wiki/Needham,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "newton": { paragraph: "Settled in 1639 as part of Cambridge, Newton separated on December 15, 1681, as Cambridge Village, was renamed Newtown in 1691 and Newton in 1766, and became a city on January 5, 1874. Water power at Newton Upper Falls and Lower Falls ran mills making snuff, chocolate, glue, and paper, though never enough to turn Newton into a factory city. Instead, the Boston and Worcester railroad reached West Newton in 1834, wealthy Bostonians built commuter estates, and late-19th-century streetcars and 1920s automobiles filled in the rest. The result is a city of thirteen villages, from Auburndale and Waban to Nonantum, Newtonville, and Chestnut Hill. Federal houses are scarce: the Jackson Homestead, a farmhouse from 1809, and a house of about 1800 at 173-175 Ward Street are among the few. The John A. Fenno House of about 1854 is a rare local Gothic Revival example, and the United Parish of Auburndale, from 1857, is the oldest wooden church in the city. The Charles River wraps the north and west edges. Population peaked at 92,384 in 1960.", sources: ["https://en.wikipedia.org/wiki/Newton,_Massachusetts"], checked: "2026-11-17" },
  "norfolk": { paragraph: "Norfolk lies on an upper valley of the Charles, and was known as North Wrentham until it separated from Wrentham in 1870. Half a dozen farms existed after 1669; they were abandoned during King Philip's War and repopulated later that century. Villages grew around sawmills and gristmills at City Mills (1680), Highland Lake (after 1691) and Pondville (after 1730), three cotton companies opened at Stony Brook after 1812, and George Campbell's paper mill at Highland Lake made wrapping and building papers. The Norfolk County Railroad opened in 1849 with a station near the village center. Rockwood Road, Route 115, from the tracks to Boardman Street, keeps 19th-century houses and the 1863 Grange Hall, a former church, in a district listed in 2017. At Sullivan's Corner, where Main, Needham and Seekonk Streets meet, the oldest cemetery, from about 1736, faces four houses, and 1 Needham Street is among the best-preserved Greek Revival buildings in town. A hospital and state prison built after 1925 brought growth, with houses around Pondville and Clark Streets before 1940.", sources: ["https://en.wikipedia.org/wiki/Norfolk,_Massachusetts", "https://en.wikipedia.org/wiki/Rockwood_Road_Historic_District", "https://en.wikipedia.org/wiki/Sullivan%27s_Corner_Historic_District"], checked: "2026-11-17" },
  "northborough": { paragraph: "Worship services in 1741 at Nathaniel Oakes's house on what is now Whitney Street led to a second parish in the north of Westborough in 1744; the area became a district in 1766 and a separate town in August 1775. Near Stirrup Brook a monument marks where Mary Goodnow was killed in a 1707 raid while a neighbor escaped to the garrison house. At 62 Whitney Street, minister Peter Whitney rebuilt his parsonage after a fire in 1780. Wilder Bush arrived from Hudson in 1839 and started comb manufacturing across from his house at 35 Whitney Street; by 1855 combs, buttons, and jewelry made from horn, bone, and shell were the town's leading industry, which lasted into the early 1900s. Brickyards also supplied the one-story gabled brick district schools built in the 1830s and 1840s, when the town was growing fast. When Route 20 was straightened in the late 1920s, Chet's Diner, Worcester Lunch Car No. 177, opened on the new stretch in 1931. Population more than doubled between 1950 and 1960, from 3,122 to 6,687.", sources: ["https://www.northboroughma.gov/sites/g/files/vyhlif12221/f/pages/final_report_phase_i.pdf", "https://en.wikipedia.org/wiki/Northborough,_Massachusetts"], checked: "2026-11-17" },
  "northbridge": { paragraph: "Settled around 1704, this land belonged to Mendon and then Uxbridge until it became a separate town on July 14, 1772. The Blackstone and Mumford Rivers drove its industry, and one family shaped most of it: Paul Whitin's 1826 brick mill still stands at the heart of Whitinsville, and the Whitin Machine Works, active from 1831 to 1964, became at its peak the largest maker of textile machinery in the world. The Whitinsville Historic District, listed in 1983, takes in Church, East, Fletcher, Hill, Woodland, Lake, and Water Streets with mills, company worker housing, the 1913 Social Library, and the 1938 post office. In Rockdale, the Paul Whitin Company put up six-unit rowhouses around 1915 and triple-decker blocks with porches and polygonal bays around 1917 on McBride, Plantation, and Taft Streets. Linwood has its own historic district along Linwood Avenue and Maple and Pine Courts. Population rose from 2,230 in 1850 to 10,174 in 1920 and reached 16,335 in 2020.", sources: ["https://en.wikipedia.org/wiki/Northbridge,_Massachusetts", "https://en.wikipedia.org/wiki/Whitinsville_Historic_District", "https://en.wikipedia.org/wiki/Rockdale_Common_Housing_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "norwood": { paragraph: "Ezra Morse made the first settlement here in 1678, putting up a sawmill in what is now South Norwood, and farming families followed over the next half-century. For nearly two more centuries the area belonged to Dedham, until Norwood became its own town in 1872. Growth was fast afterward, from 2,845 residents in 1880 to 12,627 by 1920 and a peak of 30,815 in 1970. Shortly before the split, Francis Olney Winslow built Oak View Mansion, between 1868 and 1870. The Morrill Memorial Library, designed by Joseph Ladd Neal, followed in 1898 and 1899. The town square is dominated by the Norwood Memorial Municipal Building at 566 Washington Street, a Late Gothic Revival hall of Weymouth seam-faced granite dedicated in 1928, with a 50-bell carillon in its tower and a National Register listing from 1996. The F. Holland Day House at 93 Day Street, listed in 1977, now houses the Norwood Historical Society. The Neponset River crosses the town on its way from Foxborough to Boston Harbor.", sources: ["https://en.wikipedia.org/wiki/Norwood,_Massachusetts", "https://en.wikipedia.org/wiki/Norwood_Memorial_Municipal_Building", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "oxford": { paragraph: "French Huguenot refugees put up a fort here in 1694, and its remains still lie near Huguenot Road; that first colony collapsed after the Johnson Massacre, which is marked near the south end of Main Street. Incorporation came in 1713, and English families founded a new church around 1720. Main Street itself, from Huguenot Street north to Front Street, became a 95-acre National Register district in 2011, dominated by 19th-century Greek Revival buildings along with the 1793 Universalist church, the 1829 First Congregational Church, the John Wetherell Store of about 1817, and the Classical Revival Charles Larned Memorial Library of 1903. Homes are spread across Oxford Center, North Oxford, where Route 20 crosses, and Rochdale. Much of the town sits in the flood plain of the French River, and federal engineers finished Hodges Village Dam in 1959 in response to the 1936 floods. Oxford grew from about 1,000 residents in 1790 to 13,709 in 2010.", sources: ["https://en.wikipedia.org/wiki/Oxford,_Massachusetts", "https://en.wikipedia.org/wiki/Oxford_Main_Street_Historic_District", "https://en.wikipedia.org/wiki/Hodges_Village_Dam"], checked: "2026-11-17" },
  "paxton": { paragraph: "Paxton sits at an elevation of about 1,158 feet, on land taken from Leicester and Rutland when the district was incorporated in February 1765. European settlement had begun in 1749, and the meeting house frame went up on June 18, 1766; the bell in town was cast by Paul Revere. The name honors Charles Paxton, a marshal of the Admiralty Court who reportedly promised a church bell that never arrived. On Turkey Hill Brook, which falls 90 feet over a 400-foot run, at least five water-powered mills operated from as early as 1747; Moore State Park keeps a restored sawmill and foundations, and part of it became a National Register district in 2004. Asnebumskit Hill carried an early FM broadcasting antenna from 1939, and Asnebumskit Pond supplies the town's drinking water. Residents numbered 820 in 1850 and just 416 in 1910; the count then jumped 125 percent between 1950 and 1960 and reached 5,004 in 2020.", sources: ["https://en.wikipedia.org/wiki/Paxton,_Massachusetts", "https://en.wikipedia.org/wiki/Moore_State_Park"], checked: "2026-11-17" },
  "peabody": { paragraph: "Roger Conant's colonists from Cape Ann settled this land as part of Salem in 1626. It became the South Parish of the Danvers district in 1752, the town of South Danvers in 1855, and was renamed Peabody on April 30, 1868, for the financier George Peabody, whose 1852 bequest founded the Peabody Institute Library. Potters made redware along the Central Street corridor in the 1700s, and leather became the main industry: tanneries lined Walnut Street, once nicknamed Ottoman Street, into the second half of the 20th century. Civic and business leaders built their houses in what is now the Washington Street Historic District. A 1915 school fire on Chestnut Street that killed 21 children led Peabody to become the first U.S. city to require push-open doors in public buildings. West Peabody stayed mostly farmland until the 1950s, and the population rose from 22,645 in 1950 to 48,080 in 1970; Northshore Mall opened on former Derby farmland in 1958. The Ipswich River forms the northwest border, and the 275-acre Brooksby Farm is still worked.", sources: ["https://en.wikipedia.org/wiki/Peabody,_Massachusetts"], checked: "2026-11-17" },
  "princeton": { paragraph: "Carved from Rutland land, Princeton was settled in 1743 and incorporated in 1759, taking its name from the Rev. Thomas Prince. The town sits at about 1,175 feet on the flank of Mount Wachusett, whose 2,006-foot summit, shared with Westminster, is the highest point in Massachusetts east of the Connecticut River. At Hubbardston and Mountain Roads, the center's historic district began in 1999 with just the common, the town hall, and the public library, and grew in 2006 to 165 acres covering much of the village. In East Princeton, Keyes Brook powered mid-19th-century mills such as the Stuart Chair Factory, founded in 1841, and the village along Main Street became a 200-acre district in 2004. Several resort hotels operated here in the late 19th and early 20th centuries; the best preserved is Fernside at 162 Mountain Road, a Federal house from 1835 turned summer hotel around 1870 and, from 1890, a vacation house for working women. West Village and Russell Corner are also on the National Register.", sources: ["https://en.wikipedia.org/wiki/Princeton,_Massachusetts", "https://en.wikipedia.org/wiki/Mount_Wachusett", "https://en.wikipedia.org/wiki/Princeton_Center_Historic_District", "https://en.wikipedia.org/wiki/East_Princeton_Village_Historic_District", "https://en.wikipedia.org/wiki/Fernside-Vacation_House_for_Working_Girls"], checked: "2026-11-17" },
  "quincy": { paragraph: "Settled in 1625 as Mount Wollaston, Quincy spent more than a century as the North Precinct of Braintree before becoming its own town in 1792 and a city in 1888. Stone built its economy: the Granite Railway of 1826, the first commercial railroad in the country, hauled granite from West Quincy to the Neponset for the Bunker Hill Monument, and the old pits are now the Quincy Quarries Reservation. The Old Colony Railroad opened in 1845, and in 1870 the Bellevue Land Company began laying out suburban lots in the north, while Wollaston grew as an early commuter suburb. Shipbuilding took hold at Fore River in the 1880s, and the population jumped from 47,876 in 1920 to 71,983 in 1930. Germantown began in the 1750s as a planned manufacturing village, and Adams Shore and Squantum started as summer resorts. Quincy Center keeps City Hall, the Thomas Crane Public Library and the United First Parish Church. The city has 16.8 square miles of land on Quincy Bay, with Chickatawbut Hill in the Blue Hills reaching 517 feet.", sources: ["https://en.wikipedia.org/wiki/Quincy,_Massachusetts"], checked: "2026-11-17" },
  "randolph": { paragraph: "Once the south precinct of Braintree, Randolph was settled around 1710 and incorporated in 1793, taking its name from Peyton Randolph, first president of the Continental Congress. Boot and shoe making became the main business by the mid-1800s, and by 1850 the town ranked among the country's leading boot producers. That trade paid for Stetson Hall at 6 South Main Street, a 1842 Greek Revival building with six fluted Ionic columns funded by Amasa Stetson; it served as town hall for most of its life, was restored between 1995 and 2009, and won National Register status in 2011. The Jonathan Belcher House of 1806 is also listed, as is the Gills Farm Archaeological District. When shoemaking faded in the early 1900s, light industry and commuters took its place, and population rose from 6,553 in 1930 to 27,035 in 1970. The Turner family gave the Turner Free Library building in 1875. The Cochato and Blue Hill rivers drain the town's 10.5 square miles toward the Neponset.", sources: ["https://en.wikipedia.org/wiki/Randolph,_Massachusetts", "https://en.wikipedia.org/wiki/Stetson_Hall"], checked: "2026-11-17" },
  "reading": { paragraph: "Lynn residents asked in 1639 for an inland plantation, and Reading was incorporated on June 10, 1644; the present town grew from the part once called Wood End or the Third Parish, while land north of the Ipswich River left in 1853 as North Reading. Parker Tavern on Washington Street, built in 1694, is the oldest surviving building and is kept by the Reading Antiquarian Society. The Andover-Medford Turnpike of 1806-07, today's Route 28, and the Boston and Maine Railroad of 1845 opened the town to Boston markets. Workshops made furniture, clocks and organ pipes; by the mid-1800s there were thirteen chair and cabinet makers, and shoemaking moved from cottages into factories, later joined by casket and necktie production. After southern markets fell away during the Civil War, Reading became a commuter town. The Common Historic District and the Woburn Street Historic District hold much of the older fabric, and the Walnut Street School and the Stephen Hall House are individually listed. The town covers 9.9 square miles of land.", sources: ["https://en.wikipedia.org/wiki/Reading,_Massachusetts"], checked: "2026-11-17" },
  "rutland": { paragraph: "Known to the Nipmuc as Naquag, Rutland was incorporated in 1713 with a territory that also held what are now Barre, Hubbardston, Oakham, Princeton, and the northern half of Paxton. The common stands about 1,200 feet above sea level, and the town is described as the highest ground between the Berkshires and the Atlantic; the Central Tree on Central Tree Road marks the approximate geographic center of Massachusetts. During the Revolution, camps in northern Rutland held captured Hessian soldiers. The best-known house is at 344 Main Street: a two-story, five-bay clapboard frame with a hipped roof, twin interior brick chimneys, and a pilastered doorway, built between 1760 and 1765 by Loyalist John Murray. Massachusetts confiscated it during the war, and General Rufus Putnam lived there from 1781 to 1788 before leaving to help found Marietta, Ohio; it became a National Historic Landmark in 1972. The town had only 980 residents in 1890 and has grown to 9,049 by 2020.", sources: ["https://en.wikipedia.org/wiki/Rutland,_Massachusetts", "https://en.wikipedia.org/wiki/Gen._Rufus_Putnam_House"], checked: "2026-11-17" },
  "salem": { paragraph: "Roger Conant's party came from Cape Ann to Naumkeag in 1626, and Salem was chartered as a city on March 23, 1836. Its wealth came by sea: cod, the China trade and Sumatran pepper made it the sixth-largest American city by 1790, and the Custom House, where Nathaniel Hawthorne oversaw the port from 1846 to 1849, is now part of Salem Maritime National Historic Site. When shipping faded, tanneries, shoe factories and the Naumkeag Steam Cotton Company took over. Seventeenth-century houses survive, including the Jonathan Corwin House of about 1642, the Pickman House, the Gedney House at High and Summer Streets, and the 1668 House of the Seven Gables. Federal-era mansions, many by Samuel McIntire, fill the McIntire Historic District of 407 buildings, which includes Chestnut Street. The Great Salem Fire of 1914 destroyed more than 400 homes and left 3,500 families homeless but spared Chestnut Street. Salem sits between Salem Harbor and Beverly Harbor, with the North, South and Forest rivers and Salem Neck, where the Willows became a park in 1858.", sources: ["https://en.wikipedia.org/wiki/Salem,_Massachusetts"], checked: "2026-11-17" },
  "saugus": { paragraph: "North America's first integrated iron works began producing on the Saugus River in 1646 under the name Hammersmith and shut down around 1670; excavation started in 1948, and the reconstructed site became the Saugus Iron Works National Historic Site in 1968. Saugus itself split from Lynn on February 17, 1815, as a farm town of 784 people. Shoes and woolens were made in Saugus Center, while Cliftondale and East Saugus turned out tobacco; after the Civil War, Waitt & Bond's cigar works in Cliftondale and the East Saugus snuff factory were major producers. The Saugus Branch Railroad carried passengers from 1853 to 1958, with stops at Saugus Center, Cliftondale and Pleasant Hills. The current Town Hall on Central Street dates from 1875, the same year the Civil War monument rose in the Saugus Center rotary, and the 1837 first town hall now serves the American Legion. The Newburyport Turnpike of 1805, now Route 1, runs about four miles through town. Rumney Marsh fills the southern end along the Pines River, and Breakheart Reservation covers much of the north.", sources: ["https://en.wikipedia.org/wiki/Saugus,_Massachusetts"], checked: "2026-11-17" },
  "sharon": { paragraph: "Sharon started as the second precinct of Stoughton in 1740, became the district of Stoughtonham in 1765, and gained town status in August 1775. In 1783 it took the name Sharon, after the plain in Israel, because of its heavy forest. During the Revolution its foundry cast cannon and cannonballs for the Continental Army, and the Stoughtonham Furnace Site, partly in Foxborough, earned landmark status in 1984. The Boston and Providence Railroad opened its Sharon station in 1835, replaced by a larger building in 1871, while Lake Massapoag drove the town's early growth as a summer resort. North Main Street from Post Office Square to School Street gained local protection in 1970 and federal listing in 1975. Cobb's Tavern at 41 Bay Road, a National Historic Landmark, forms a second local district, and Stoneholm at 188 Ames Street was designated in 1980. Borderland, on Massapoag Street, is a National Register district shared with Easton. The 1950s brought a 108 percent jump, to 10,070 residents by 1960.", sources: ["https://en.wikipedia.org/wiki/Sharon,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "sherborn": { paragraph: "Sherborn, incorporated in 1674, lies 18 miles southwest of Boston, and most of its small water area is in Farm Pond. The Sherborn Center Historic District, bordered by Farm, Sawin, Washington and North Main Streets, Zion's Lane and the CSX tracks, is mostly residential with a cluster of civic and church buildings. Only two things there survive from the early town: the first cemetery, laid out in 1689, and the older part of the Flagg House at 22 Washington Street, built around 1740 and the only building in the center that predates 1750. Two churches date to about 1830: the Pilgrim Church at 25 South Main Street, given Italianate details in the 1850s, and the Greek Revival First Parish Church at 11 Washington Street. The Town Hall at 3 Sanger Street is a rare unaltered work of Worcester architects Boyden & Ball, with deep bracketed eaves, quoined corners and a cupola. The Tudor Revival Dowse Memorial Building of 1914, built for the library, now holds town offices. The National Register added the district in 1986.", sources: ["https://en.wikipedia.org/wiki/Sherborn,_Massachusetts", "https://en.wikipedia.org/wiki/Sherborn_Center_Historic_District"], checked: "2026-11-17" },
  "shirley": { paragraph: "Once part of the Plantation of Groton, Shirley was first settled by English pioneers around 1720 and separated from Groton in 1753, taking the name of Governor William Shirley. Its original center is the Shirley Center Historic District, a 1753 common from which Brown, Center, Horsepond, Parker and Whitney Roads radiate, with the town hall, the First Parish Congregational Church and Georgian, Federal and Greek Revival buildings. Industry grew to the south along Catacoonamug Brook, where a gristmill and sawmill stood by 1740, and the railroad arrived in 1845. The Shirley Village Historic District, with 441 properties, includes the large Phoenix Mills building, many vernacular wood-frame houses built south of the tracks in the later 1800s and a Richardsonian Romanesque library trimmed in brownstone. A paper mill opened around 1790 and the first of seven cotton mills in 1812, and two large 19th-century mill buildings have been subdivided for businesses. Shirley Shaker Village, founded in 1793 and closed in 1908, survives on the grounds of a state prison. The Squannacook and Nashua Rivers bound the town.", sources: ["https://en.wikipedia.org/wiki/Shirley,_Massachusetts", "https://en.wikipedia.org/wiki/Shirley_Center_Historic_District", "https://en.wikipedia.org/wiki/Shirley_Village_Historic_District"], checked: "2026-11-17" },
  "shrewsbury": { paragraph: "Gersham Wheelock arrived as the first permanent settler in 1720, the common was laid out in 1721, and Shrewsbury was incorporated in 1727. Apple orchards anchored the early farm economy, a leather trade began in 1786, and Luther Goddard started making brass clocks in 1809. Around the common, a 14-acre district listed in 1976 includes the 1766 First Congregational Church, built partly from timbers of the 1722 meetinghouse, an 1830 brick schoolhouse, the 1797 Sumner House, and the Renaissance Revival public library of 1903. On Main Street opposite Dean Park, the Artemas Ward House, built in 1727 by the general's father, is now a Harvard-owned museum. Nineteenth-century visitors to Lake Quinsigamond supported market gardens, and lakeside cottages followed; streetcar lines encouraged single-family houses, and population nearly quadrupled from 1,946 in 1910 to 7,586 in 1940. The 1953 Worcester tornado killed twelve people in the Shrewsbury area. After that the curve steepened, to 16,622 in 1960 and 38,325 in 2020.", sources: ["https://en.wikipedia.org/wiki/Shrewsbury,_Massachusetts", "https://en.wikipedia.org/wiki/Shrewsbury_Historic_District_(Shrewsbury,_Massachusetts)", "https://en.wikipedia.org/wiki/Artemas_Ward_House"], checked: "2026-11-17" },
  "somerville": { paragraph: "For two centuries the land known as \"beyond the Neck\" belonged to Charlestown; it became the town of Somerville on March 3, 1842, and a city in 1872. Washington Street and Broadway both trace roads laid out in the 1630s, and the Old Powder House at Broadway and College Avenue began as an early-1700s windmill before the colony bought it in 1747. Prospect Hill anchored Continental Army lines during the Siege of Boston. The Middlesex Canal arrived in 1803 and the Fitchburg Railroad carried passengers from 1843; brickyards, the American Tube Works of 1851 and later meatpacking plants followed, and at one point the city had eight passenger rail stations. Population went from 3,540 in 1850 to 103,908 in 1930, and building continued into the 1940s, leaving a dense \"city of homes\" at about 19,650 people per square mile. The city has 84 National Register listings and is built over seven drumlins, among them Winter, Spring and Prospect hills, between the Mystic River, Alewife Brook and Miller's River. Squares such as Davis, Union, Ball and Magoun grew around rail stops.", sources: ["https://en.wikipedia.org/wiki/Somerville,_Massachusetts"], checked: "2026-11-17" },
  "southborough": { paragraph: "Settlement began in 1660, and in July 1727 the south borough of Marlborough was incorporated as Southborough. Farms came first, then mills on small rivers that by the end of the 19th century made plaster, straw bonnets, boots and shoes. That manufacturing vanished after Boston dammed the area for reservoirs in the 1890s, and the town saw little growth until the high-tech boom of the 1970s; the Sudbury Reservoir still floods about one-tenth of its land. The Southborough Center Historic District runs along Main Street from the Fay School grounds to the railroad crossing east of Latisquama Road, around the junction with Marlboro and Cordaville Roads. It keeps the 18th-century common, burying ground and stone-walled animal pound, while Alexander Rice Esty designed both the 1870 Italianate town house and the Episcopal church. The railroad arrived in 1850. Cordaville, Fayville and Southville remain the town's villages, and in 2021 residential use covered 43 percent of its land.", sources: ["https://en.wikipedia.org/wiki/Southborough,_Massachusetts", "https://en.wikipedia.org/wiki/Sudbury_Dam_Historic_District", "https://en.wikipedia.org/wiki/Southborough_Center_Historic_District"], checked: "2026-11-17" },
  "spencer": { paragraph: "Nathaniel Wood cleared the first homestead in 1717, Samuel Bemis made settlement permanent in 1721, and the town split from Leicester in April 1753. The Seven Mile River powered the first mill in 1740 and remained the main water source for later industry. After the Embargo Act of 1807, shoemaking and wire drawing took over: Josiah Green opened a shoe factory in 1834, the Prouty family built theirs in 1855, and the wire trade begun by Elliot Prouty in 1812 grew to 11 factories. As bootmaking moved into factories, the center expanded to house workers, and population reached 8,747 by 1890. Spencer's town center district, first registered in 1986 and enlarged three times, covers Main Street between High and North Streets, residential blocks on Grove, Prouty, Pleasant, and High Streets, and mill areas along Cherry, Wall, and Mechanic Streets, mostly from the late 19th century. Howe State Park marks the birthplace of Elias Howe, inventor of the sewing machine.", sources: ["https://en.wikipedia.org/wiki/Spencer,_Massachusetts", "https://en.wikipedia.org/wiki/Spencer_Town_Center_Historic_District"], checked: "2026-11-17" },
  "sterling": { paragraph: "Settlers from Lancaster moved into the area called Chocksett in 1720, seven years after Tahanto sold the land, and families such as Beman, Sawyer, Houghton and Osgood are remembered in the names of the oldest roads. After decades as the Second Parish of Lancaster, the village was incorporated as Sterling in 1781, named for General William Alexander, known as Lord Stirling. Surveyors set out the town common in 1724, and the Sterling Center Historic District around it, roughly bounded by Meetinghouse Hill and Main, Maple, Kendall Hill, Boulding, Worcester and Princeton Streets, keeps 18th- and 19th-century houses, several churches and the 1835 town hall. Federal listing of that district came in 1988. A Native fort and graveyard once stood between East Waushacum Pond and West Waushacum Pond. Interstate 190 cuts the town in half, and Routes 12, 62, 110 and 140 also cross its 31.7 square miles, which meet Boylston at the Wachusett Reservoir.", sources: ["https://en.wikipedia.org/wiki/Sterling,_Massachusetts", "https://en.wikipedia.org/wiki/Sterling_Center_Historic_District"], checked: "2026-11-17" },
  "stoneham": { paragraph: "Governor Winthrop's party found Spot Pond in 1632 and ate lunch on Cheese Rock, today's Bear Hill. Colonists settled this corner of Charlestown in 1634, and on December 17, 1725, the General Court made \"Charlestown End\" the township of Stoneham. A meetinghouse and the Old Burying Ground date from 1726. The town stayed small through the colonial era and then became a major shoe-manufacturing center during the Industrial Revolution; a small \"ten footer\" shop from that trade, the Shoe Shop-Doucette Ten Footer, is individually listed. Population went from 2,085 in 1850 to 10,060 by 1930 and 20,725 by 1970. Listed buildings include the Dow Block, the Oddfellows Building, the South School, the old firehouse and the William Bryant Octagon House, and the Nobility Hill Historic District protects a residential area. Within the Middlesex Fells portion of town lie the Spot Pond Archeological District and the Fells Reservoirs Historic District. Stoneham Center has no commuter rail station; Interstate 93 crosses town at Montvale Avenue.", sources: ["https://en.wikipedia.org/wiki/Stoneham,_Massachusetts"], checked: "2026-11-17" },
  "stoughton": { paragraph: "Split from the southwest corner of Dorchester, Stoughton was incorporated on December 22, 1726, and later lost territory to Sharon, Canton and, in 1888, Avon. Farming came first; the Littlefield brothers opened the first shoe factory in East Stoughton in 1815. Rail service arrived on March 18, 1845, and the boot and shoe trade expanded until the Civil War, much of it selling to the South. Manufacturers entertained buyers in their own homes, among them the George Monk and Henry Fitzpatrick houses on Pleasant Street. The 1888 depot, built of granite from Myron Gilbert's quarry off West Street, is the only Massachusetts station with a clock tower and was listed in 1974. Street railways reached Brockton in 1895 and Boston by 1899, and the old Belcher Last factory has since been turned into elderly housing. Population nearly doubled between 1955 and 1975. Villages such as North, West and South Stoughton, Eastondale and Brockton Heights spread across 16.3 square miles, and Ames Long Pond is the main swimming pond.", sources: ["https://stoughtonhistory.com/beyond.htm", "https://en.wikipedia.org/wiki/Stoughton,_Massachusetts"], checked: "2026-11-17" },
  "stow": { paragraph: "Stow was incorporated in 1683 on roughly 40 square miles known as Pompositticut Plantation, then gave up land to Harvard (1732), Shirley (1765), Boxborough (1783), Hudson (1866) and Maynard (1871), leaving 18.1 square miles. Apart from factories at Assabet Village and Rock Bottom, later Maynard and Gleasondale, the town stayed sparsely settled farm and orchard land until the 1950s. The first settlement lay a mile east of today's center, at Lower Village, where the Lower Village Cemetery sits on Route 117/62. Early 18th-century timber-frame houses remain, among them the Randall–Hale Homestead at 6 Sudbury Road, begun around 1710 and enlarged around 1760, and the Brown–Stow House, whose rear lean-to gives it a saltbox shape. Gleasondale, shared with Hudson, took its name in 1898 from mill owners Gleason and Dale. The Assabet River crosses town from west to east under three bridges, and Lake Boon and White's Pond are the other major waters. In 1942 the Army took about a tenth of the town for munitions storage; that land joined the Assabet River National Wildlife Refuge in 2005.", sources: ["https://en.wikipedia.org/wiki/Stow,_Massachusetts", "https://en.wikipedia.org/wiki/Randall%E2%80%93Hale_Homestead", "https://en.wikipedia.org/wiki/Brown%E2%80%93Stow_House"], checked: "2026-11-17" },
  "sudbury": { paragraph: "Sudbury was incorporated in 1639 and once included what is now Wayland, which split off in 1780. Its first meetinghouse stood near the Sudbury River, but in 1723 the West Parish meetinghouse was built at Rocky Plains, the present town center. The Sudbury Center Historic District on Concord and Old Sudbury Roads, listed in 1976 with 80 buildings, includes the Israel Loring Parsonage of about 1730, the 1797 First Parish Meetinghouse and the 1793 Hosmer House; the Town Hall dates to 1932, after the 1846 Town House burned. On Old Boston Post Road, the Wayside Inn, run as Howe's Tavern by 1716, was bought by Henry Ford in 1923, and he added a grist mill, the Martha-Mary Chapel and the Redstone School moved from Sterling. After World War II, Raytheon and other employers drew rapid growth, and one-acre zoning shaped developments of single-family Colonials and large Capes in the 1970s and 1980s. Commerce stayed on Route 20, while open space was kept along the Hop Brook corridor and in the northern half of town.", sources: ["https://en.wikipedia.org/wiki/Sudbury,_Massachusetts", "https://en.wikipedia.org/wiki/Sudbury_Center_Historic_District", "https://en.wikipedia.org/wiki/Wayside_Inn_Historic_District"], checked: "2026-11-17" },
  "sutton": { paragraph: "Proprietors led by Edward Pratt received an eight-mile-square grant here in 1704, and Sutton was incorporated in 1716, a year before the Great Snow buried the settlers' cabins. Over time Sutton gave up land to form Grafton in 1735 and Millbury in 1813. The 1737 Edward Putnam House appears on the town seal. Homes are spread among five villages: Manchaug, South Sutton, Sutton Center, West Sutton, and Wilkinsonville. Manchaug was farmland until Rhode Island investors bought Mumford River water rights in 1826 and put up the stone mill at 9 Main Street, followed by gable-roofed, multifamily wood-frame worker housing and single-family homes for supervisors; the mills closed in 1921 and the company houses were sold off in 1927. Manchaug won federal listing in 2018, joining the Sutton Center and West Sutton districts, both listed in 2001, and the Waters Farm on Waters Road. Population roughly doubled between 1970 and 2000, from 4,590 to 8,250.", sources: ["https://en.wikipedia.org/wiki/Sutton,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts", "https://en.wikipedia.org/wiki/Manchaug_Village_Historic_District"], checked: "2026-11-17" },
  "upton": { paragraph: "Farm families on the edges of Hopkinton, Mendon, Uxbridge, and Sutton wanted a church closer to home, and in 1735 the General Court assembled Upton from pieces of all four, seven years after the first European settlement. Small shoe shops operated here from about 1730 to 1850, and by 1837 Upton made more than a fifth of the boots produced in Worcester County. William Knowlton's hat business, begun in partnership in 1835, grew into the Second Empire factory at 134 Main Street, expanded with a tower in 1872 when it was called the largest women's hat factory in the world; it became senior housing in 1985. Central Square, site of the first meetinghouse and the town green, anchors a 73-acre historic district listed in 2015, with the 1884 town hall, three mid-19th-century churches, and a residential area to the south. Upton State Forest on Westborough Road holds a separate district of Civilian Conservation Corps work. The population dipped to 1,693 in 1920 and reached 8,000 in 2020.", sources: ["https://en.wikipedia.org/wiki/Upton,_Massachusetts", "https://en.wikipedia.org/wiki/Knowlton_Hat_Factory", "https://en.wikipedia.org/wiki/Upton_Center_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "uxbridge": { paragraph: "Western Mendon became Uxbridge in 1727, with the first town meeting held at the Farnum House, built in 1710 and now home to the historical society; Northbridge remained part of the town until 1772. The Tafts bridged the Blackstone River in 1709, and the Blackstone Canal later carried barges to Providence until the Providence and Worcester Railroad ended canal traffic in 1848. Daniel Day's 1809 woolen mill was followed by Clapp's cotton mill in North Uxbridge and Ezra Benson's Rivulet Mill in 1814; by 1855 twenty mills employed about 560 workers. Mill settlements formed at Ironstone, Hecla, Wheelockville, North Uxbridge, and Rogerson's Village, where the Crown and Eagle Mill was renovated after a 1971 fire. Quaker families from Smithfield, Rhode Island, built mills and houses, and abolitionists Abby Kelley Foster and Effingham Capron came from their meeting. Downtown, the Uxbridge Common District on North Main and Court Streets, listed in 1984, is dominated by Federal-style buildings such as the 1818 Uxbridge Academy.", sources: ["https://en.wikipedia.org/wiki/Uxbridge,_Massachusetts", "https://en.wikipedia.org/wiki/Uxbridge_Common_District"], checked: "2026-11-17" },
  "wakefield": { paragraph: "The first corn mill of old Reading stood on the Mill River at Water Street, and the town's original parish later became South Reading, incorporated on February 25, 1812. In 1868 Cyrus Wakefield paid for land and a new town hall, and the town took his name; that building, now named for William J. Lee, stands at 1 Lafayette Street. Wakefield had founded the Rattan Works in 1856 to make wicker furniture, and the Wakefield Rattan Company grew to about 1,000 workers. The rail line between Wilmington and Boston was built in 1844, a stove foundry opened in 1854, and the Boston Ice Company began cutting on Lake Quannapowitt in 1851. Older homes cluster in the Church-Lafayette Streets Historic District, which includes the Col. James Hartshorne House, and around the Upper and Lower Commons. Population grew from 2,407 in 1850 to 25,402 in 1970, after Route 128 reached the north edge by 1958. Neighborhoods such as Greenwood, Woodville, Lakeside and Montrose surround the 247-acre lake and Crystal Lake, a drinking-water reservoir.", sources: ["https://en.wikipedia.org/wiki/Wakefield,_Massachusetts"], checked: "2026-11-17" },
  "walpole": { paragraph: "First settled in 1659 inside Dedham, Walpole asked to separate and was refused by Dedham's town meeting in 1721; the General Court created the town in May 1724 and named it for Sir Robert Walpole. Its earliest sawmill, owned by Joshua Fisher and Major Eleazer Lusher, stood near School Meadow Brook and the Neponset River, on ground that is now the Walpole Town Forest. From about 1860, mills producing cotton, lumber, and paper were built along the Neponset's falls. The largest, the Bird Company complex in East Walpole, closed in 1980; most of it was torn down and housing now covers much of the site. The Birds also left Francis William Bird Park, 89 acres laid out by John Nolen in 1925. On West Street, the Deacon Willard Lewis House, kept by the Walpole Historical Society, gained a National Register listing in 1975. Blackburn Hall, a red-brick neoclassical memorial, was dedicated in 1932. Postwar growth was steep, with population rising from 9,109 in 1950 to 18,149 in 1970.", sources: ["https://en.wikipedia.org/wiki/Walpole,_Massachusetts", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Norfolk_County,_Massachusetts"], checked: "2026-11-17" },
  "waltham": { paragraph: "English settlers reached Waltham in 1634 as part of Watertown, gained independence as a town in 1738, and won city status in 1884. By 1813 the Boston Manufacturing Company was running what is called the first integrated textile mill in the United States, powered by dams on the Charles River, and in the 1830s the company gave the town the land for its central square. The railroad and the Moody Street bridge followed in the 1840s. The Waltham Watch Company, opened in 1854, was the first to make watches on an assembly line and gave the city its Watch City name; its red-brick Romanesque complex at 185-241 Crescent Street on the Charles River's south bank, built from 1879 into the 1910s, now holds homes and businesses. Around the common, the Central Square district includes a brick Queen Anne fire station of 1887 on Lexington Street and a Georgian Revival City Hall from 1924 to 1926. Older estates survive as well, including Theodore Lyman's of 1793, Christopher Gore's mansion of 1806, and the Robert Treat Paine Estate of 1886.", sources: ["https://en.wikipedia.org/wiki/Waltham,_Massachusetts", "https://en.wikipedia.org/wiki/Central_Square_Historic_District_(Waltham,_Massachusetts)", "https://en.wikipedia.org/wiki/American_Waltham_Watch_Company_Historic_District"], checked: "2026-11-17" },
  "watertown": { paragraph: "English settlers led by Richard Saltonstall and George Phillips founded Watertown in 1630, beside a Massachusett herring weir at the spot now occupied by the Watertown Dam on the Charles River. The colony's first gristmill went up around 1632, and a woolen mill followed in 1662. Over the next two centuries Watertown land went into Weston, Waltham, Lincoln and Belmont. From 1816 to 1995 the Watertown Arsenal shaped the east end along Arsenal Street; the National Register site now holds Arsenal Yards and the Mosesian Center for the Arts. Stanley Steamer automobiles were built here starting in 1897. Older houses still stand, including the Browne House at 562 Main Street, built between about 1694 and 1701, and the 1772 Edmund Fowle House on Marshall Street. Today's neighborhoods include Watertown Square, Coolidge Square, Bemis, East Watertown and the West End, packed into 4.12 square miles. The Charles forms much of the southern and eastern line with Brighton, and Mount Auburn Cemetery, founded in 1831, fills most of the Cambridge edge.", sources: ["https://en.wikipedia.org/wiki/Watertown,_Massachusetts"], checked: "2026-11-17" },
  "wayland": { paragraph: "Sudbury Plantation's first settlement, in 1638, was on land that is now Wayland. The eastern parish separated in 1722, was incorporated on April 10, 1780, as East Sudbury, and took the name Wayland in 1835 to honor Francis Wayland, then president of Brown University. Today's village center began forming in 1814 and 1815, when a new meetinghouse went up at the corner of what are now Route 20 and Route 27 to replace the meetinghouse of 1726. That crossroads is the Wayland Center Historic District, a 21-acre district placed on the federal Register in 1974, where most buildings predate 1850 and are wood-frame Federal or Greek Revival structures, along with two 19th-century barns. The railroad station opened in 1881 and began Wayland's shift toward a Boston commuter suburb. The largest jump came in the 1950s, when population rose 137 percent to 10,444 by 1960. Cochituate is a separate census-designated village, and Dudley Pond lies within the town's 15.9 square miles.", sources: ["https://en.wikipedia.org/wiki/Wayland,_Massachusetts", "https://en.wikipedia.org/wiki/Wayland_Center_Historic_District"], checked: "2026-11-17" },
  "webster": { paragraph: "Before 1832, the ground under today's Webster was divided among Dudley, Oxford, and an unincorporated gore; that March the Commonwealth incorporated it. Samuel Slater, fresh from his Pawtucket mill, built several textile mills here, named the place for his friend Daniel Webster, and is buried in Mount Zion Cemetery. One of the Slater mills passed to Cranston Print Works in 1936. Between 1850 and 1920 the head count grew more than fivefold, to 13,258, and the commercial blocks at 175-299 Main Street have been federally listed as a group since 1982, two years after the nearby Shumway and Spaulding blocks were listed on their own. On Main, Negus, and Lake Streets, a small civic district registered in 2012 groups the 1903-05 Bartlett High School, now senior housing, with the 1927-28 town hall and the Chester C. Corbin Public Library of 1920, designed by Edward Lippincott Tilton. Webster Lake, officially Lake Chaubunagungamaug and known for its 45-character Nipmuc name, ranks among the largest lakes in Massachusetts and hosts the Indian Ranch concert venue.", sources: ["https://en.wikipedia.org/wiki/Webster,_Massachusetts", "https://en.wikipedia.org/wiki/Webster_Municipal_Buildings_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "wellesley": { paragraph: "Until 1881 Wellesley was West Needham, the western part of a town that had itself been cut from Dedham. Residents voted to secede on October 23, 1880, and the legislature created the town the following April, naming it after Horatio Hollis Hunnewell's estate, Wellesley. Trains have run to Boston since 1833, and the population nearly doubled in the 1920s, from 6,224 to 11,439, then passed 20,000 by 1950. The Hunnewell Estates Historic District, along Washington Street and Pond Road between the Charles River and Lake Waban, holds family houses built from 1765 to 1891: the Colonial Welles House of 1770, Arthur Gilman's Italianate Hunnewell house of 1851, a Queen Anne cottage of 1870, and a Stick-style house of 1875. Its lakeshore Italian Garden, from 1854, is described as the country's first topiary garden. On Cottage Street, a locally designated district preserves houses built mostly around the 1860s. The town is divided into villages such as Wellesley Hills, Wellesley Farms, Wellesley Lower Falls, and Babson Park.", sources: ["https://en.wikipedia.org/wiki/Wellesley,_Massachusetts", "https://en.wikipedia.org/wiki/Hunnewell_Estates_Historic_District"], checked: "2026-11-17" },
  "west-boylston": { paragraph: "Incorporated in 1808 from parts of Lancaster, Shrewsbury, Boylston, Holden, and Sterling, West Boylston grew through the 1800s on textile mills and reached 3,019 residents in 1890. Then Boston needed water. Starting in 1897, the Wachusett Dam impounded the Nashua River, and West Boylston gave up about 2,200 acres, more than any other town: over 1,700 residents, 300 homes, eight schools, six mills, and four churches were moved or lost, and by 1910 the population had fallen to 1,270. The reservoir first filled in May 1908. The Old Stone Church was left standing on the shore as a reminder and joined the National Register in 1973. Across the water on Route 140, Oakdale sits where the Stillwater and Quinapoxet Rivers meet; because reservoir construction halted development there in the 1890s, its houses remain mostly Greek Revival with a smaller number of Victorian ones, protected as a historic district since 1996. The Quinapoxet River Bridge on Thomas Street was listed in 1990.", sources: ["https://en.wikipedia.org/wiki/West_Boylston,_Massachusetts", "https://en.wikipedia.org/wiki/Oakdale_Village_Historic_District", "https://en.wikipedia.org/wiki/National_Register_of_Historic_Places_listings_in_Worcester_County,_Massachusetts"], checked: "2026-11-17" },
  "westborough": { paragraph: "A handful of families settled near Lake Chauncy in the \"west borough\" of Marlborough around 1675, and on November 18, 1717, Westborough was incorporated with 27 families as the 100th town in Massachusetts. Eli Whitney, inventor of the cotton gin, was born here in 1765. The Boston-Worcester road became a turnpike in 1810, today's Route 9, and once the steam railroad arrived the commercial center moved downtown; factories went on to ship boots and shoes, straw hats, sleighs, bicycles, and abrasives. That growth filled in two residential historic districts: West Main Street, a 45-acre area of Greek Revival and Late Victorian houses listed in 1987 and enlarged three times, and Vintonville east of the center, where Otis Vinton platted some of the early streets and about 80 modest houses on small lots went up along Cottage, Pine, Beach, and neighboring streets, mainly between 1860 and 1890. The State Reform School opened on Lake Chauncy in 1848; its grounds became Westborough State Hospital in 1884. Population rose from 2,371 in 1850 to 21,567 in 2020.", sources: ["https://en.wikipedia.org/wiki/Westborough,_Massachusetts", "https://en.wikipedia.org/wiki/West_Main_Street_Historic_District_(Westborough,_Massachusetts)", "https://en.wikipedia.org/wiki/Vintonville_Historic_District"], checked: "2026-11-17" },
  "westford": { paragraph: "What began as West Chelmsford, a village of Chelmsford, was incorporated as Westford on September 23, 1729. From the late 1700s into the early 1800s the local economy rested on granite, apples, and worsted yarn, and the Abbot Worsted Company is said to have been the first American firm to spin worsted from camel hair. Graniteville was known mainly for its quarries until the railroad came in 1847, after which Charles G. Sargent built a mill there and the village grew fast. The Graniteville Historic District, which spans 150 acres bounded by River Street, Bridge Street, and North Main Street and entered the Register in 2002, keeps much of that late-19th-century housing along with several quarry sites. Other villages include Forge Village, Nabnasset, Parker Village, and the town center around Westford Common on Main Street, where the Henry Fletcher House dates to about 1813 and the J.V. Fletcher Library to 1895. Population jumped 65.6 percent in the 1960s, to 10,368, and later tech employers clustered along Route 110 beside I-495.", sources: ["https://en.wikipedia.org/wiki/Westford,_Massachusetts", "https://en.wikipedia.org/wiki/Graniteville_Historic_District_(Westford,_Massachusetts)"], checked: "2026-11-17" },
  "weston": { paragraph: "Weston began as the outlying farms of the Watertown settlement of 1630. Those farms became a separate precinct with its own meetinghouse in 1698, and the Farmers' Precinct was incorporated as Weston in 1713. With little good farmland or water power, the town lived off the main road west from Boston, and taverns and shops grew along the Boston Post Road and North Avenue; the Golden Ball Tavern and the Josiah Smith Tavern survive from the 1700s. Grist and sawmills worked Stony Brook, the Worcester Turnpike (now Route 9) opened in 1810, and the Hook & Hastings organ factory moved to the North Avenue area in 1888. Country estates spread from the 1860s, and growth after World War II followed Route 128 and the Massachusetts Turnpike. The town counts ten National Register districts, among them Boston Post Road, Kendal Green, Silver Hill, and Case's Corner. The Weston Aqueduct and Reservoir date from 1901 to 1903, and more than 2,000 acres, about 18 percent of the town, are kept as open land.", sources: ["https://en.wikipedia.org/wiki/Weston,_Massachusetts"], checked: "2026-11-17" },
  "weymouth": { paragraph: "Thomas Weston's Wessagusset colony of 1622 failed, but the settlement that followed it made Weymouth the second-oldest in Massachusetts after Plymouth; the name dates from 1635. Shoemaking was under way by the early 1700s and ended only in 1973, when the Stetson Shoe Company closed, and its factory now holds medical offices. The Bickman House at 84 Sea Street, from about 1650, is probably the oldest surviving house, and Abigail Adams was born in town. The current Town Hall, built in 1928, copies Boston's Old State House. Four village centers organize the town: Weymouth Landing on the Braintree line, East Weymouth with Jackson Square and Queen Anne, shingle and Colonial Revival houses on streets such as Hillcrest Road, South Weymouth around Columbian Square, and dense North Weymouth, where waterfront cottages on Regatta Road are being renovated. The 1950s and 1960s brought the biggest growth, to 48,177 people by 1960. Hingham Bay forms the northern edge, the Fore and Back rivers cut through, and the town is especially exposed to sea level rise.", sources: ["https://en.wikipedia.org/wiki/Weymouth,_Massachusetts"], checked: "2026-11-17" },
  "winchester": { paragraph: "Before its incorporation on April 30, 1850, Winchester went by Waterfield, then Black Horse Village, then South Woburn, and its land was split among Woburn, Medford, Arlington and Cambridge. The new town was named for Colonel William P. Winchester, who pledged $3,000 toward the first town hall. The Middlesex Canal crossed it from 1803 to 1836 until the Boston and Lowell Railroad, with two stations in town, took over and drew new settlement. Industry included the Beggs and Cobb tannery and the Winn Watch Hand factory, but by the early 1900s Winchester had become a commuter town; population rose from 7,248 in 1900 to 22,269 in 1970. Older properties include the Wright-Locke Farm, the John Mason House and the Capt. Josiah Locke House, along with St. Mary's Catholic Church on the National Register. A central valley left by an ancient course of the Merrimack carries the Aberjona River past Wedge Pond to the Mystic Lakes on the southern edge, while the Middlesex Fells and its reservoirs cover the eastern third.", sources: ["https://en.wikipedia.org/wiki/Winchester,_Massachusetts"], checked: "2026-11-17" },
  "woburn": { paragraph: "Woburn's first settlers arrived in 1640 near Horn Pond, and the town incorporated in 1642 over a territory that once included Winchester, Burlington and parts of Stoneham and Wilmington. Leather shaped it early: Gershom Flagg opened a tannery in 1668, and another followed at Cummingsville in 1823. Loammi Baldwin's Middlesex Canal opened in 1803, and a section still runs beside the Baldwin House. Trains of the Boston and Lowell came through in 1835, and Woburn became a city on June 12, 1888. In Woburn Center, the Winn Memorial Library, designed by Henry Hobson Richardson, opened in 1879 and now serves as the public library, near the 1860 First Congregational Church and the National Register-listed First Burial Ground. The Benjamin Thompson House, birthplace of Count Rumford, and the 1790 House also survive. Route 128 opened in 1951 and Interstate 93 arrived in 1963, bringing office parks and commercial growth. Horn Pond still supplies city water through five wells, and the Aberjona River runs through the 12.9-square-mile city.", sources: ["https://en.wikipedia.org/wiki/Woburn,_Massachusetts"], checked: "2026-11-17" },
  "worcester": { paragraph: "Two English attempts to settle Quinsigamond collapsed in war, in 1675 and 1702, before Jonas Rice resettled it for good in 1713; Worcester was incorporated as a town in 1722 and chartered as a city in 1848. The Blackstone Canal opened in 1828 and the Worcester and Boston Railroad in 1835, and Ichabod Washburn's wire works, founded in 1831, grew into the largest wire maker in the country. Waves of Irish, Swedish, French, Polish, Lithuanian, Italian, and other immigrants filled neighborhoods such as Quinsigamond Village, Vernon Hill, Union Hill, Kelley Square, and Shrewsbury Street, and the three-decker, a balloon-framed wooden house with a bay window on each floor and rear porches, lined the new streets; frontage-based sewer charges pushed builders toward narrow lots. Many of those three-deckers have been added to the National Register since 1990. The city spreads over more than seven hills, Lake Quinsigamond runs about four miles along the Shrewsbury line, and the F4 tornado of June 9, 1953, killed 94 people.", sources: ["https://en.wikipedia.org/wiki/Worcester,_Massachusetts", "https://en.wikipedia.org/wiki/Triple-decker"], checked: "2026-11-17" },
  "wrentham": { paragraph: "Dedham men explored the lakes around Wollomonopoag in 1660, the town bought 600 acres in 1661, and the General Court separated the settlement as Wrentham on October 16, 1673; it was burned during King Philip's War. Franklin was formed from its western part in 1778, North Wrentham left in 1870 and Plainville split off in 1905. Wrentham sat on the stagecoach route between Boston and Providence, and David Fisher built the two-story Federal-style Roebuck Tavern at 21 Dedham Street in 1795. The town's first congregation, formed in 1692, worships in an 1834 Greek Revival church with a Doric portico and a four-stage tower rebuilt after the 1938 hurricane. At 127 South Street, the 1868 Plimpton–Winter House, with its low hip roof and bracketed eaves, is regarded as the town's finest Italianate house. North of the center, the Wrentham State School campus was first built between 1909 and 1917. Lake Pearl and Lake Archer lie toward the center of town, and Sheldonville, the old farming section in the west, still has commercial orchards.", sources: ["https://en.wikipedia.org/wiki/Wrentham,_Massachusetts", "https://en.wikipedia.org/wiki/Franklin,_Massachusetts", "https://en.wikipedia.org/wiki/Roebuck_Tavern", "https://en.wikipedia.org/wiki/Original_Congregational_Church_of_Wrentham", "https://en.wikipedia.org/wiki/Plimpton%E2%80%93Winter_House", "https://en.wikipedia.org/wiki/Wrentham_Developmental_Center"], checked: "2026-11-17" },
};
